import { useEffect, useState } from "react";

interface Document {
  id: string;
  title: string;
  description: string;
  date: string;
  category: string;
}

export function DocumentArchiveView() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchDocuments();
  }, []);

  const fetchDocuments = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/document-processing-service/documents');
      if (!response.ok) {
        throw new Error(`Failed to fetch documents: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setDocuments(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/document-processing-service/documents/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete document: ${response.status} ${response.statusText}`);
      }
      // Refresh the list after deletion
      fetchDocuments();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (documents.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No documents found.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Document Archive</h1>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
        {documents.map((doc) => (
          <div key={doc.id} style={{
            border: '1px solid #ccc',
            borderRadius: '8px',
            padding: '15px',
            width: '100%',
            boxSizing: 'border-box'
          }}>
            <h3>{doc.title}</h3>
            <p>{doc.description}</p>
            <p><strong>Date:</strong> {doc.date}</p>
            <p><strong>Category:</strong> {doc.category}</p>
            <button 
              onClick={() => handleDelete(doc.id)}
              style={{
                backgroundColor: '#ff4d4d',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                padding: '8px 12px',
                cursor: 'pointer',
                marginTop: '10px'
              }}
            >
              Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
