  const sql = `SELECT * FROM monitor_results WHERE target_id = ? ORDER BY timestamp DESC LIMIT 1`;
  const stmt = db.prepare(sql);
  const result = stmt.get(targetId) as Record<string, unknown> | undefined;
  if (!result) return undefined;
  return {
    id: Number(result.id),
    targetId: Number(result.target_id),
    timestamp: Number(result.timestamp),
    status: Boolean(result.status),
    responseTime: Number(result.response_time)
  };
}

