import { Router, type Request, type Response } from "express";
import { db, deleteRecord, getAllRecords, getRecordById, insertRecord, updateRecord } from "../db/crm-records-table";

export const router = Router();

// Get all records
router.get("/records", (req: Request, res: Response) => {
  try {
    const records = getAllRecords();
    res.json(records);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch records" });
  }
});

// Get a record by ID
router.get("/records/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID" });
    }

    const record = getRecordById(id);
    if (!record) {
      return res.status(404).json({ error: "Record not found" });
    }

    res.json(record);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch record" });
  }
});

// Create a new record
router.post("/records", (req: Request, res: Response) => {
  try {
    const { objectType, data } = req.body;

    if (!objectType || !data) {
      return res.status(400).json({ error: "objectType and data are required" });
    }

    const newId = insertRecord(objectType, data);
    res.status(201).json({ id: newId, objectType, data });
  } catch (error) {
    res.status(500).json({ error: "Failed to create record" });
  }
});

// Update a record
router.put("/records/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { objectType, data } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID" });
    }

    if (!objectType || !data) {
      return res.status(400).json({ error: "objectType and data are required" });
    }

    const updatedRows = updateRecord(id, objectType, data);
    if (updatedRows === 0) {
      return res.status(404).json({ error: "Record not found" });
    }

    res.json({ id, objectType, data });
  } catch (error) {
    res.status(500).json({ error: "Failed to update record" });
  }
});

// Delete a record
router.delete("/records/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID" });
    }

    const deletedRows = deleteRecord(id);
    if (deletedRows === 0) {
      return res.status(404).json({ error: "Record not found" });
    }

    res.json({ message: "Record deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete record" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip authentication for non-protected routes
  if (req.method === "GET" && req.path === "/") {
    return next();
  }

  // Check for JWT in Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
  }

  const secretBuffer = Buffer.from(secret);
  const tokenParts = token.split(".");
  if (tokenParts.length !== 3) {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }

  const payloadAndSignature = tokenParts[0] + "." + tokenParts[1];
  const expectedSignature = createHmac("sha256", secretBuffer)
    .update(payloadAndSignature)
    .digest();

  const actualSignature = Buffer.from(tokenParts[2], "base64");

  try {
    if (!timingSafeEqual(expectedSignature, actualSignature)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }
  } catch {
    return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
  }

  // If we get here, the token is valid
  next();
}

import { useEffect, useState } from "react";

interface Contact {
  id: string;
  name: string;
  email: string;
  phone: string;
}

interface Deal {
  id: string;
  title: string;
  value: number;
  status: string;
}

interface CustomObject {
  id: string;
  name: string;
  description: string;
}

export function CrmWorkspace() {
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [deals, setDeals] = useState<Deal[]>([]);
  const [customObjects, setCustomObjects] = useState<CustomObject[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [contactsRes, dealsRes, customObjectsRes] = await Promise.all([
          fetch('/api/crm-api/contacts'),
          fetch('/api/crm-api/deals'),
          fetch('/api/crm-api/custom-objects')
        ]);

        if (!contactsRes.ok || !dealsRes.ok || !customObjectsRes.ok) {
          throw new Error('Failed to fetch data');
        }

        const [contactsData, dealsData, customObjectsData] = await Promise.all([
          contactsRes.json(),
          dealsRes.json(),
          customObjectsRes.json()
        ]);

        setContacts(contactsData);
        setDeals(dealsData);
        setCustomObjects(customObjectsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleAddContact = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const newContact = {
      name: formData.get('name') as string,
      email: formData.get('email') as string,
      phone: formData.get('phone') as string
    };

    try {
      const res = await fetch('/api/crm-api/contacts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newContact)
      });

      if (res.ok) {
        const createdContact = await res.json();
        setContacts([...contacts, createdContact]);
        form.reset();
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteContact = async (id: string) => {
    try {
      const res = await fetch(`/api/crm-api/contacts/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        setContacts(contacts.filter(contact => contact.id !== id));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleAddDeal = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const newDeal = {
      title: formData.get('title') as string,
      value: Number(formData.get('value')),
      status: formData.get('status') as string
    };

    try {
      const res = await fetch('/api/crm-api/deals', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newDeal)
      });

      if (res.ok) {
        const createdDeal = await res.json();
        setDeals([...deals, createdDeal]);
        form.reset();
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteDeal = async (id: string) => {
    try {
      const res = await fetch(`/api/crm-api/deals/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        setDeals(deals.filter(deal => deal.id !== id));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleAddCustomObject = async (e: React.FormEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const newCustomObject = {
      name: formData.get('name') as string,
      description: formData.get('description') as string
    };

    try {
      const res = await fetch('/api/crm-api/custom-objects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newCustomObject)
      });

      if (res.ok) {
        const createdCustomObject = await res.json();
        setCustomObjects([...customObjects, createdCustomObject]);
        form.reset();
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteCustomObject = async (id: string) => {
    try {
      const res = await fetch(`/api/crm-api/custom-objects/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        setCustomObjects(customObjects.filter(obj => obj.id !== id));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>CRM Workspace</h1>

      <section style={{ marginBottom: '30px' }}>
        <h2>Contacts</h2>
        <form onSubmit={handleAddContact} style={{ marginBottom: '20px' }}>
          <input
            type="text"
            name="name"
            placeholder="Name"
            required
            style={{ width: '100%', padding: '8px', marginBottom: '10px' }}
          />
          <input
            type="email"
            name="email"
            placeholder="Email"
            required
            style={{ width: '100%', padding: '8px', marginBottom: '10px' }}
          />
          <input
            type="tel"
            name="phone"
            placeholder="Phone"
            style={{ width: '100%', padding: '8px', marginBottom: '10px' }}
          />
          <button type="submit" style={{ padding: '8px 16px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px' }}>
            Add Contact
          </button>
        </form>

        {contacts.length === 0 ? (
          <p>No contacts found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {contacts.map(contact => (
              <div key={contact.id} style={{ border: '1px solid #ccc', padding: '10px', borderRadius: '4px' }}>
                <strong>{contact.name}</strong> - {contact.email} - {contact.phone}
                <button 
                  onClick={() => handleDeleteContact(contact.id)}
                  style={{ marginLeft: '10px', padding: '4px 8px', backgroundColor: '#dc3545', color: 'white', border: 'none', borderRadius: '4px' }}
                >
                  Delete
                </button>
              </div>
            ))}
          </div>
        )}
      </section>

      <section style={{ marginBottom: '30px' }}>
        <h2>Deals</h2>
        <form onSubmit={handleAddDeal} style={{ marginBottom: '20px' }}>
          <input
            type="text"
            name="title"
            placeholder="Title"
            required
            style={{ width: '100%', padding: '8px', marginBottom: '10px' }}
          />
          <input
            type="number"
            name="value"
            placeholder="Value"
            required
            style={{ width: '100%', padding: '8px', marginBottom: '10px' }}
          />
          <input
            type="text"
            name="status"
            placeholder="Status"
            required
            style={{ width: '100%', padding: '8px', marginBottom: '10px' }}
          />
          <button type="submit" style={{ padding: '8px 16px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px' }}>
            Add Deal
          </button>
        </form>

        {deals.length === 0 ? (
          <p>No deals found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {deals.map(deal => (
              <div key={deal.id} style={{ border: '1px solid #ccc', padding: '10px', borderRadius: '4px' }}>
                <strong>{deal.title}</strong> - ${deal.value} - {deal.status}
                <button 
                  onClick={() => handleDeleteDeal(deal.id)}
                  style={{ marginLeft: '10px', padding: '4px 8px', backgroundColor: '#dc3545', color: 'white', border: 'none', borderRadius: '4px' }}
                >
                  Delete
                </button>
              </div>
            ))}
          </div>
        )}
      </section>

      <section>
        <h2>Custom Objects</h2>
        <form onSubmit={handleAddCustomObject} style={{ marginBottom: '20px' }}>
          <input
            type="text"
            name="name"
            placeholder="Name"
            required
            style={{ width: '100%', padding: '8px', marginBottom: '10px' }}
          />
          <textarea
            name="description"
            placeholder="Description"
            style={{ width: '100%', padding: '8px', marginBottom: '10px' }}
          />
          <button type="submit" style={{ padding: '8px 16px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px' }}>
            Add Custom Object
          </button>
        </form>

        {customObjects.length === 0 ? (
          <p>No custom objects found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {customObjects.map(obj => (
              <div key={obj.id} style={{ border: '1px solid #ccc', padding: '10px', borderRadius: '4px' }}>
                <strong>{obj.name}</strong> - {obj.description}
                <button 
                  onClick={() => handleDeleteCustomObject(obj.id)}
                  style={{ marginLeft: '10px', padding: '4px 8px', backgroundColor: '#dc3545', color: 'white', border: 'none', borderRadius: '4px' }}
                >
                  Delete
                </button>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

