import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip authentication for non-protected routes
  if (req.method === "GET" && req.path === "/") {
    return next();
  }

  // Check for JWT in Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  const token = authHeader.substring(7);

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
  }

  const secretBuffer = Buffer.from(secret);
  const tokenParts = token.split(".");
  if (tokenParts.length !== 3) {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }

  const payloadAndSignature = tokenParts[0] + "." + tokenParts[1];
  const expectedSignature = createHmac("sha256", secretBuffer)
    .update(payloadAndSignature)
    .digest();

  const actualSignature = Buffer.from(tokenParts[2], "base64");

  try {
    if (!timingSafeEqual(expectedSignature, actualSignature)) {
      return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    }
  } catch {
    return res.status(401).json({ error: "Unauthorized: Invalid token signature" });
  }

  // If we get here, the token is valid
  next();
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface VaultItem {
  id: number;
  title: string;
  username: string;
  password: string;
  url: string;
  notes: string;
  attachment_id: number | null;
  collection_id: number | null;
  created_at: string;
  updated_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS vault_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    username TEXT NOT NULL,
    password TEXT NOT NULL,
    url TEXT,
    notes TEXT,
    attachment_id INTEGER,
    collection_id INTEGER,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllVaultItems(): VaultItem[] {
  const stmt = db.prepare(`SELECT * FROM vault_items`);
  return stmt.all() as unknown as VaultItem[];
}

export function getVaultItemById(id: number): VaultItem | undefined {
  const stmt = db.prepare(`SELECT * FROM vault_items WHERE id = ?`);
  return stmt.get(id) as unknown as VaultItem | undefined;
}

export function insertVaultItem(
  title: string,
  username: string,
  password: string,
  url: string,
  notes: string,
  attachment_id: number | null,
  collection_id: number | null
): number {
  const stmt = db.prepare(
    `INSERT INTO vault_items (title, username, password, url, notes, attachment_id, collection_id, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))`
  );
  const result = stmt.run(title, username, password, url, notes, attachment_id, collection_id);
  return Number(result.lastInsertRowid);
}

export function updateVaultItem(
  id: number,
  title: string,
  username: string,
  password: string,
  url: string,
  notes: string,
  attachment_id: number | null,
  collection_id: number | null
): void {
  const stmt = db.prepare(
    `UPDATE vault_items
     SET title = ?, username = ?, password = ?, url = ?, notes = ?, attachment_id = ?, collection_id = ?, updated_at = datetime('now')
     WHERE id = ?`
  );
  stmt.run(title, username, password, url, notes, attachment_id, collection_id, id);
}

export function deleteVaultItem(id: number): void {
  const stmt = db.prepare(`DELETE FROM vault_items WHERE id = ?`);
  stmt.run(id);
}

