import { Router, type Request, type Response } from "express";
import {
  getAllVaultItems,
  getVaultItemById,
  insertVaultItem,
  updateVaultItem,
  deleteVaultItem
} from "../db/vault-items-table";

export const router = Router();

// Get all vault items
router.get("/", (req: Request, res: Response) => {
  try {
    const items = getAllVaultItems();
    res.json(items);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch vault items" });
  }
});

// Get a specific vault item by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const item = getVaultItemById(id);
    if (!item) {
      return res.status(404).json({ error: "Vault item not found" });
    }

    res.json(item);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch vault item" });
  }
});

// Create a new vault item
router.post("/", (req: Request, res: Response) => {
  try {
    const { title, username, password, url, notes, attachment_id, collection_id } = req.body;

    // Validate required fields
    if (!title || !username || !password) {
      return res.status(400).json({ error: "Title, username, and password are required" });
    }

    const newItem = insertVaultItem(title, username, password, url || "", notes || "", attachment_id || null, collection_id || null);
    res.status(201).json(newItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to create vault item" });
  }
});

// Update an existing vault item
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { title, username, password, url, notes, attachment_id, collection_id } = req.body;

    // Validate required fields
    if (!title || !username || !password) {
      return res.status(400).json({ error: "Title, username, and password are required" });
    }

    const existingItem = getVaultItemById(id);
    if (!existingItem) {
      return res.status(404).json({ error: "Vault item not found" });
    }

    updateVaultItem(id, title, username, password, url || "", notes || "", attachment_id || null, collection_id || null);
    const updatedItem = getVaultItemById(id);
    res.json(updatedItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to update vault item" });
  }
});

// Delete a vault item
