  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const existingItem = getVaultItemById(id);
    if (!existingItem) {
      return res.status(404).json({ error: "Vault item not found" });
    }

    deleteVaultItem(id);
    res.json({ message: "Vault item deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete vault item" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const MFA_REQUIRED_PATHS = [
  "/login",
  "/dashboard",
  "/settings",
];

const MFA_REQUIRED_METHODS = ["POST", "PUT", "DELETE"];

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip MFA check for non-protected routes/methods
  const isProtectedPath = MFA_REQUIRED_PATHS.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !MFA_REQUIRED_METHODS.includes(req.method)) {
    next();
    return;
  }

  // Check for MFA token in headers
  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Validate JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  // Recreate signature for verification
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const isValid = timingSafeEqual(
    Buffer.from(signature, "base64url"),
    Buffer.from(expectedSignature, "base64url")
  );

  if (!isValid) {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Token is valid, proceed
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to the emergency access delegation endpoint
  if (req.method !== "POST" || req.path !== "/emergency-access/delegate") {
    next();
    return;
  }

  // Check if the request has a valid authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT secret not configured" });
    return;
  }

  // Simple token validation - in a real implementation, you'd decode and verify
  // the JWT signature using HMAC-SHA256 with the secret
  try {
    // For demonstration purposes, we'll just check if the token matches a
    // predefined expected token (this is not secure in production)
    const expectedToken = createHmac("sha256", secret)
      .update("valid-emergency-access-token")
      .digest("hex");

    const tokenBuffer = Buffer.from(token);
    const expectedBuffer = Buffer.from(expectedToken);

    if (tokenBuffer.length !== expectedBuffer.length || 
        !timingSafeEqual(tokenBuffer, expectedBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

interface User {
  id: string;
  username: string;
  email: string;
  role: string;
}

interface VaultItem {
  id: string;
  title: string;
  username: string;
  password: string;
  url: string;
  notes: string;
}

export function AdminDashboard() {
  const [users, setUsers] = useState<User[]>([]);
  const [vaultItems, setVaultItems] = useState<VaultItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form states
  const [newUser, setNewUser] = useState({
    username: '',
    email: '',
    role: 'user'
  });

  const [newVaultItem, setNewVaultItem] = useState({
    title: '',
    username: '',
    password: '',
    url: '',
    notes: ''
  });

  useEffect(() => {
    fetchAllData();
  }, []);

  const fetchAllData = async () => {
    try {
      setLoading(true);
      const [usersRes, vaultRes] = await Promise.all([
        fetch('/api/vault-api/'),
        fetch('/api/vault-api/')
      ]);

      if (!usersRes.ok || !vaultRes.ok) {
        throw new Error('Failed to fetch data');
      }

      const usersData = await usersRes.json();
      const vaultData = await vaultRes.json();

      setUsers(usersData);
      setVaultItems(vaultData);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await fetch('/api/vault-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newUser)
      });

      if (res.ok) {
        setNewUser({ username: '', email: '', role: 'user' });
        fetchAllData();
      } else {
        setError('Failed to add user');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleAddVaultItem = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await fetch('/api/vault-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newVaultItem)
      });

      if (res.ok) {
        setNewVaultItem({ title: '', username: '', password: '', url: '', notes: '' });
        fetchAllData();
      } else {
        setError('Failed to add vault item');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteUser = async (id: string) => {
    try {
      const res = await fetch(`/api/vault-api/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        fetchAllData();
      } else {
        setError('Failed to delete user');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteVaultItem = async (id: string) => {
    try {
      const res = await fetch(`/api/vault-api/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        fetchAllData();
      } else {
        setError('Failed to delete vault item');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;
  }

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px'
    }}>
      <h1 style={{ textAlign: 'center' }}>Admin Dashboard</h1>

      <div style={{ marginBottom: '30px' }}>
        <h2>Manage Users</h2>
        <form onSubmit={handleAddUser} style={{ marginBottom: '20px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <input
            type="text"
            placeholder="Username"
            value={newUser.username}
            onChange={(e) => setNewUser({...newUser, username: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <input
            type="email"
            placeholder="Email"
            value={newUser.email}
            onChange={(e) => setNewUser({...newUser, email: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <select
            value={newUser.role}
            onChange={(e) => setNewUser({...newUser, role: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          >
            <option value="user">User</option>
            <option value="admin">Admin</option>
          </select>
          <button type="submit" style={{ padding: '8px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px' }}>
            Add User
          </button>
        </form>

        {users.length === 0 ? (
          <p>No users found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {users.map(user => (
              <div key={user.id} style={{
                border: '1px solid #ccc',
                borderRadius: '4px',
                padding: '10px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}>
                <div>
                  <strong>{user.username}</strong> ({user.email}) - {user.role}
                </div>
                <button 
                  onClick={() => handleDeleteUser(user.id)}
                  style={{
                    padding: '4px 8px',
                    backgroundColor: '#dc3545',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px'
                  }}
                >
                  Delete
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ marginBottom: '30px' }}>
        <h2>Manage Vault Items</h2>
        <form onSubmit={handleAddVaultItem} style={{ marginBottom: '20px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <input
            type="text"
            placeholder="Title"
            value={newVaultItem.title}
            onChange={(e) => setNewVaultItem({...newVaultItem, title: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <input
            type="text"
            placeholder="Username"
            value={newVaultItem.username}
            onChange={(e) => setNewVaultItem({...newVaultItem, username: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <input
            type="password"
            placeholder="Password"
            value={newVaultItem.password}
            onChange={(e) => setNewVaultItem({...newVaultItem, password: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <input
            type="url"
            placeholder="URL"
            value={newVaultItem.url}
            onChange={(e) => setNewVaultItem({...newVaultItem, url: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <textarea
            placeholder="Notes"
            value={newVaultItem.notes}
            onChange={(e) => setNewVaultItem({...newVaultItem, notes: e.target.value})}
            style={{ width: '100%', padding: '8px', height: '60px' }}
          />
          <button type="submit" style={{ padding: '8px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px' }}>
            Add Vault Item
          </button>
        </form>

        {vaultItems.length === 0 ? (
          <p>No vault items found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {vaultItems.map(item => (
              <div key={item.id} style={{
                border: '1px solid #ccc',
                borderRadius: '4px',
                padding: '10px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}>
                <div>
                  <strong>{item.title}</strong><br />
                  <small>{item.username} - {item.url}</small>
                </div>
                <button 
                  onClick={() => handleDeleteVaultItem(item.id)}
                  style={{
                    padding: '4px 8px',
                    backgroundColor: '#dc3545',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px'
                  }}
                >
                  Delete
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

const createTableSQL = `
  CREATE TABLE IF NOT EXISTS feed_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    url TEXT UNIQUE NOT NULL,
    published_at DATETIME NOT NULL,
    feed_id INTEGER NOT NULL,
    read_by_user BOOLEAN DEFAULT FALSE,
    tags TEXT,
    FOREIGN KEY (feed_id) REFERENCES feeds(id)
  )
`;

db.exec(createTableSQL);

export interface FeedItem {
  id: number;
  title: string;
  description: string;
  url: string;
  published_at: string;
  feed_id: number;
  read_by_user: boolean;
  tags: string;
}

export function getAllFeedItems(): FeedItem[] {
  const stmt = db.prepare(`SELECT * FROM feed_items`);
  return stmt.all() as unknown as FeedItem[];
}

export function getFeedItemById(id: number): FeedItem | undefined {
  const stmt = db.prepare(`SELECT * FROM feed_items WHERE id = ?`);
  return stmt.get(id) as unknown as FeedItem | undefined;
}

export function insertFeedItem(
  title: string,
  description: string,
  url: string,
  published_at: string,
  feed_id: number,
  read_by_user: boolean,
  tags: string
): number {
  const stmt = db.prepare(
    `INSERT INTO feed_items (title, description, url, published_at, feed_id, read_by_user, tags) VALUES (?, ?, ?, ?, ?, ?, ?)`
  );
  const result = stmt.run(title, description, url, published_at, feed_id, read_by_user, tags);
  return Number(result.lastInsertRowid);
}

export function updateFeedItem(
  id: number,
  title: string,
  description: string,
  url: string,
  published_at: string,
  feed_id: number,
