import { Router, type Request, type Response } from "express";
import { db, deleteFeedItem, getAllFeedItems, getFeedItemById, insertFeedItem, updateFeedItem } from "../db/feed-items-table";
import { middleware } from "../middleware/multiple-login-methods";

export const router = Router();

// GET /feed-aggregator - Get all feed items
router.get("/", middleware, (req: Request, res: Response) => {
  try {
    const feedItems = getAllFeedItems();
    return res.json(feedItems);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch feed items" });
  }
});

// GET /feed-aggregator/:id - Get a specific feed item by ID
router.get("/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID provided" });
    }

    const feedItem = getFeedItemById(id);
    if (!feedItem) {
      return res.status(404).json({ error: "Feed item not found" });
    }

    return res.json(feedItem);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch feed item" });
  }
});

// POST /feed-aggregator - Create a new feed item
router.post("/", middleware, (req: Request, res: Response) => {
  try {
    const { title, description, url, published_at, feed_id, read_by_user, tags } = req.body;

    if (!title || !url || !published_at || !feed_id) {
      return res.status(400).json({ error: "Missing required fields: title, url, published_at, feed_id" });
    }

    const newFeedItem = insertFeedItem(title, description, url, published_at, feed_id, read_by_user, tags);
    return res.status(201).json(newFeedItem);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create feed item" });
  }
});

// PUT /feed-aggregator/:id - Update an existing feed item
router.put("/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID provided" });
    }

    const { title, description, url, published_at, feed_id, read_by_user, tags } = req.body;

    if (!title || !url || !published_at || !feed_id) {
      return res.status(400).json({ error: "Missing required fields: title, url, published_at, feed_id" });
    }

    const existingItem = getFeedItemById(id);
    if (!existingItem) {
      return res.status(404).json({ error: "Feed item not found" });
    }

    const updatedFeedItem = updateFeedItem(id, title, description, url, published_at, feed_id, read_by_user, tags);
    return res.json(updatedFeedItem);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update feed item" });
  }
});

// DELETE /feed-aggregator/:id - Delete a feed item
router.delete("/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
