      return res.status(404).json({ error: "Feed item not found" });
    }

    deleteFeedItem(id);
    return res.json({ message: "Feed item deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete feed item" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const { username, password, token } = req.body;

  // Handle form login
  if (username && password) {
    // In a real implementation, this would validate credentials
    // For now, we'll just pass through
    next();
    return;
  }

  // Handle HTTP auth
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith("Basic ")) {
    // In a real implementation, this would validate basic auth
    // For now, we'll just pass through
    next();
    return;
  }

  // Handle OpenID Connect token
  if (token) {
    const secret = process.env.JWT_SECRET;
    if (!secret) {
      res.status(500).json({ error: "Server configuration error" });
      return;
    }

    // Simple token validation (in reality, this would decode and verify)
    const expectedToken = createHmac("sha256", secret)
      .update("valid-token")
      .digest("hex");

    const receivedToken = createHmac("sha256", secret)
      .update(token)
      .digest("hex");

    try {
      const expectedBuffer = Buffer.from(expectedToken, "hex");
      const receivedBuffer = Buffer.from(receivedToken, "hex");

      if (timingSafeEqual(expectedBuffer, receivedBuffer)) {
        next();
      } else {
        res.status(401).json({ error: "Invalid token" });
      }
    } catch {
      res.status(401).json({ error: "Invalid token" });
    }
    return;
  }

  // If no valid login method is provided
  res.status(400).json({ error: "No valid login method provided" });
}

import { useEffect, useState } from "react";

interface FeedItem {
  id: string;
  title: string;
  content: string;
  publishedAt: string;
  feedId: string;
  tags: string[];
}

interface Feed {
  id: string;
  name: string;
  url: string;
  tags: string[];
}

export function FeedReader() {
  const [feeds, setFeeds] = useState<Feed[]>([]);
  const [feedItems, setFeedItems] = useState<FeedItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchFeedsAndItems() {
      try {
        setLoading(true);
        const [feedsResponse, itemsResponse] = await Promise.all([
          fetch("/api/feed-aggregator/"),
          fetch("/api/feed-aggregator/items"),
        ]);

        if (!feedsResponse.ok || !itemsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const feedsData = await feedsResponse.json();
        const itemsData = await itemsResponse.json();

        setFeeds(feedsData);
        setFeedItems(itemsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchFeedsAndItems();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (feedItems.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No feed items available.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Feed Reader</h1>
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "15px",
          justifyContent: "center",
        }}
      >
        {feedItems.map((item) => (
          <div
            key={item.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              width: "100%",
              maxWidth: "300px",
            }}
          >
            <h3>{item.title}</h3>
            <p>{item.content}</p>
            <small>
              Published: {new Date(item.publishedAt).toLocaleString()}
            </small>
            <div style={{ marginTop: "10px" }}>
              {item.tags.length > 0 && (
                <div>
                  Tags: {item.tags.join(", ")}
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

