import { Router, type Request, type Response } from "express";
import { db, getAllWorkflows, getWorkflowById, insertWorkflow, updateWorkflow, deleteWorkflow, getAllExecutions, getExecutionsByWorkflowId, insertExecution } from "../db/workflows-table";

export const router = Router();

// Get all workflows
router.get("/workflows", (req: Request, res: Response) => {
  try {
    const workflows = getAllWorkflows();
    return res.json(workflows);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch workflows" });
  }
});

// Get a specific workflow by ID
router.get("/workflows/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid workflow ID" });
    }

    const workflow = getWorkflowById(id);
    if (!workflow) {
      return res.status(404).json({ error: "Workflow not found" });
    }

    return res.json(workflow);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch workflow" });
  }
});

// Create a new workflow
router.post("/workflows", (req: Request, res: Response) => {
  try {
    const { name, description } = req.body;

    if (!name || !description) {
      return res.status(400).json({ error: "Name and description are required" });
    }

    const id = insertWorkflow(name, description);
    const newWorkflow = getWorkflowById(id);

    if (!newWorkflow) {
      return res.status(500).json({ error: "Failed to create workflow" });
    }

    return res.status(201).json(newWorkflow);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create workflow" });
  }
});

// Update a workflow
router.put("/workflows/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid workflow ID" });
    }

    const { name, description } = req.body;

    if (!name || !description) {
      return res.status(400).json({ error: "Name and description are required" });
    }

    updateWorkflow(id, name, description);
    const updatedWorkflow = getWorkflowById(id);

    if (!updatedWorkflow) {
      return res.status(404).json({ error: "Workflow not found" });
    }

    return res.json(updatedWorkflow);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update workflow" });
  }
});

// Delete a workflow
router.delete("/workflows/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid workflow ID" });
    }

    const workflow = getWorkflowById(id);
    if (!workflow) {
      return res.status(404).json({ error: "Workflow not found" });
    }

    deleteWorkflow(id);
    return res.json({ message: "Workflow deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete workflow" });
  }
});

// Get all executions
router.get("/executions", (req: Request, res: Response) => {
  try {
    const executions = getAllExecutions();
    return res.json(executions);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch executions" });
  }
});

// Get executions by workflow ID
