import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check tokens for API routes
  if (!req.path.startsWith("/api/")) {
    next();
    return;
  }

  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation - in a real system, you'd decode and verify the JWT signature
  // For this implementation, we'll assume the token is a simple string that matches the secret
  const expectedToken = createHmac("sha256", secret).update("api-access").digest("hex");

  try {
    const expectedBuffer = Buffer.from(expectedToken);
    const providedBuffer = Buffer.from(token);

    if (expectedBuffer.length !== providedBuffer.length) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }

    const isValid = timingSafeEqual(expectedBuffer, providedBuffer);

    if (!isValid) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

