import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./server-hosting-panel.db");

interface ServerRow {
  id: number;
  name: string;
  owner_id: number;
  config: string;
  created_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS servers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    owner_id INTEGER NOT NULL,
    config TEXT NOT NULL,
    created_at TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllServers(): ServerRow[] {
  const stmt = db.prepare("SELECT * FROM servers");
  return stmt.all() as unknown as ServerRow[];
}

export function getServerById(id: number): ServerRow | undefined {
  const stmt = db.prepare("SELECT * FROM servers WHERE id = ?");
  return stmt.get(id) as unknown as ServerRow | undefined;
}

export function insertServer(name: string, ownerId: number, config: string): number {
  const stmt = db.prepare(
    "INSERT INTO servers (name, owner_id, config, created_at) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(name, ownerId, config, new Date().toISOString());
  return Number(result.lastInsertRowid);
}

export function updateServer(id: number, name: string, ownerId: number, config: string): void {
  const stmt = db.prepare(
    "UPDATE servers SET name = ?, owner_id = ?, config = ? WHERE id = ?"
  );
  stmt.run(name, ownerId, config, id);
}

export function deleteServer(id: number): void {
  const stmt = db.prepare("DELETE FROM servers WHERE id = ?");
  stmt.run(id);
}

