import { Router, type Request, type Response } from "express";
import { 
  getAllDocuments,
  getDocumentById,
  insertDocument,
  updateDocument,
  deleteDocument,
  getAllSignatureRequests,
  getSignatureRequestsByDocumentId,
  insertSignatureRequest,
  updateSignatureRequestStatus,
  deleteSignatureRequest
} from "../db/documents-table";

export const router = Router();

// Get all documents
router.get("/documents", (req: Request, res: Response) => {
  try {
    const documents = getAllDocuments();
    res.json(documents);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch documents" });
  }
});

// Get a document by ID
router.get("/documents/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid document ID" });
    }

    const document = getDocumentById(id);
    if (!document) {
      return res.status(404).json({ error: "Document not found" });
    }

    res.json(document);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch document" });
  }
});

// Create a new document
router.post("/documents", (req: Request, res: Response) => {
  try {
    const { title, content } = req.body;

    if (!title || !content) {
      return res.status(400).json({ error: "Title and content are required" });
    }

    const id = insertDocument(title, content);
    const newDocument = getDocumentById(id);

    if (!newDocument) {
      return res.status(500).json({ error: "Failed to create document" });
    }

    res.status(201).json(newDocument);
  } catch (error) {
    res.status(500).json({ error: "Failed to create document" });
  }
});

// Update a document
router.put("/documents/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid document ID" });
    }

    const { title, content } = req.body;

    if (!title || !content) {
      return res.status(400).json({ error: "Title and content are required" });
    }

    const existingDocument = getDocumentById(id);
    if (!existingDocument) {
      return res.status(404).json({ error: "Document not found" });
    }

    updateDocument(id, title, content);
    const updatedDocument = getDocumentById(id);

    if (!updatedDocument) {
      return res.status(500).json({ error: "Failed to update document" });
    }

    res.json(updatedDocument);
  } catch (error) {
    res.status(500).json({ error: "Failed to update document" });
  }
});

// Delete a document
router.delete("/documents/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid document ID" });
    }

    const existingDocument = getDocumentById(id);
    if (!existingDocument) {
      return res.status(404).json({ error: "Document not found" });
    }

    deleteDocument(id);
    res.json({ message: "Document deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete document" });
  }
});

// Get all signature requests
router.get("/signature-requests", (req: Request, res: Response) => {
  try {
    const signatureRequests = getAllSignatureRequests();
    res.json(signatureRequests);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch signature requests" });
  }
});

// Get signature requests by document ID
router.get("/signature-requests/document/:documentId", (req: Request, res: Response) => {
  try {
    const documentId = Number(req.params.documentId);
    if (isNaN(documentId)) {
      return res.status(400).json({ error: "Invalid document ID" });
    }

    const signatureRequests = getSignatureRequestsByDocumentId(documentId);
    res.json(signatureRequests);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch signature requests" });
  }
});

// Create a new signature request
router.post("/signature-requests", (req: Request, res: Response) => {
  try {
    const { documentId, signerEmail } = req.body;

    if (!documentId || !signerEmail) {
      return res.status(400).json({ error: "Document ID and signer email are required" });
    }

    const id = insertSignatureRequest(documentId, signerEmail);
    const newSignatureRequest = {
      id,
      documentId,
      signerEmail,
      status: "pending" as const
    };

    res.status(201).json(newSignatureRequest);
  } catch (error) {
    res.status(500).json({ error: "Failed to create signature request" });
  }
});

// Update signature request status
router.put("/signature-requests/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid signature request ID" });
    }

    const { status, signedAt } = req.body;

    if (!status) {
      return res.status(400).json({ error: "Status is required" });
    }

    const validStatuses = ["pending", "signed"];
    if (!validStatuses.includes(status)) {
      return res.status(400).json({ error: "Invalid status. Must be 'pending' or 'signed'" });
    }

    updateSignatureRequestStatus(id, status, signedAt);

    res.json({ message: "Signature request status updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update signature request" });
  }
});

// Delete a signature request
router.delete("/signature-requests/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid signature request ID" });
    }

    deleteSignatureRequest(id);
    res.json({ message: "Signature request deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete signature request" });
  }
});

import { useEffect, useState } from "react";

export function DocumentSigningUi() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchDocuments();
  }, []);

  const fetchDocuments = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/signing-workflow-api/documents');
      if (!response.ok) {
        throw new Error(`Failed to fetch documents: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setDocuments(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;

  if (documents.length === 0) return <div style={{ textAlign: 'center', padding: '20px' }}>No documents available.</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Document Signing</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {documents.map(doc => (
          <div key={doc.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
            <h2>{doc.title}</h2>
            <p>{doc.description}</p>
            <p><strong>Status:</strong> {doc.status}</p>
            <button 
              onClick={() => window.open(`/api/signing-workflow-api/documents/${doc.id}/pdf`, '_blank')}
              style={{ 
                backgroundColor: '#007bff', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px', 
                padding: '8px 12px', 
                cursor: 'pointer' 
              }}
            >
              View Document
            </button>
            <button 
              onClick={async () => {
                try {
                  const response = await fetch(`/api/signing-workflow-api/documents/${doc.id}`, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ status: 'signed' })
                  });
                  if (!response.ok) {
                    throw new Error(`Failed to update document: ${response.status} ${response.statusText}`);
                  }
                  fetchDocuments(); // Refresh the list
                } catch (err) {
                  setError(err instanceof Error ? err.message : 'An unknown error occurred');
                }
              }}
              style={{ 
                backgroundColor: '#28a745', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px', 
                padding: '8px 12px', 
                marginLeft: '10px', 
                cursor: 'pointer' 
              }}
            >
              Sign Document
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

