export function getAllStockItems(): StockItem[] {
  const stmt = db.prepare(`SELECT * FROM stock_items`);
  return stmt.all() as unknown as StockItem[];
}

export function getStockItemById(id: number): StockItem | undefined {
  const stmt = db.prepare(`SELECT * FROM stock_items WHERE id = ?`);
  return stmt.get(id) as unknown as StockItem | undefined;
}

export function insertStockItem(
  name: string,
  quantity: number,
  unit: string,
  expiry_date: string,
  last_consumed: string | null
): number {
  const stmt = db.prepare(
    `INSERT INTO stock_items (name, quantity, unit, expiry_date, last_consumed) VALUES (?, ?, ?, ?, ?)`
  );
  const result = stmt.run(name, quantity, unit, expiry_date, last_consumed);
  return Number(result.lastInsertRowid);
}

export function updateStockItem(
  id: number,
  name: string,
  quantity: number,
  unit: string,
  expiry_date: string,
  last_consumed: string | null
): void {
  const stmt = db.prepare(
    `UPDATE stock_items SET name = ?, quantity = ?, unit = ?, expiry_date = ?, last_consumed = ? WHERE id = ?`
  );
  stmt.run(name, quantity, unit, expiry_date, last_consumed, id);
}

export function deleteStockItem(id: number): void {
  const stmt = db.prepare(`DELETE FROM stock_items WHERE id = ?`);
  stmt.run(id);
}

