import { useEffect, useState } from "react";

interface Expense {
  id: number;
  description: string;
  amount: number;
  category: string;
}

export function ExpensesList() {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchExpenses();
  }, []);

  const fetchExpenses = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/expenses-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setExpenses(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const groupByCategory = (expenses: Expense[]) => {
    return expenses.reduce((acc, expense) => {
      if (!acc[expense.category]) {
        acc[expense.category] = [];
      }
      acc[expense.category].push(expense);
      return acc;
    }, {} as Record<string, Expense[]>);
  };

  const categories = groupByCategory(expenses);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (expenses.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No expenses logged yet.</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Expenses</h1>
      {Object.entries(categories).map(([category, categoryExpenses]) => (
        <div key={category} style={{ marginBottom: "30px" }}>
          <h2 style={{ borderBottom: "1px solid #ccc", paddingBottom: "5px" }}>{category}</h2>
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {categoryExpenses.map((expense) => (
              <div 
                key={expense.id} 
                style={{ 
                  border: "1px solid #ddd", 
                  borderRadius: "8px", 
                  padding: "10px", 
                  display: "flex", 
                  justifyContent: "space-between", 
                  alignItems: "center"
                }}
              >
                <span>{expense.description}</span>
                <span>${expense.amount.toFixed(2)}</span>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Expense {
  id: number;
  amount: number;
  category: string;
  date: string;
}

interface MonthlyTotal {
  month: string;
  totals: {
    [category: string]: number;
  };
  total: number;
}

export function MonthlyTotalsView() {
  const [monthlyTotals, setMonthlyTotals] = useState<MonthlyTotal[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchMonthlyTotals() {
      try {
        const response = await fetch("/api/expenses-api/");
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const expenses: Expense[] = await response.json();

        // Group expenses by month and category
        const monthlyTotalsMap: { [key: string]: MonthlyTotal } = {};

        expenses.forEach(expense => {
          const date = new Date(expense.date);
          const monthKey = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;

          if (!monthlyTotalsMap[monthKey]) {
            monthlyTotalsMap[monthKey] = {
              month: monthKey,
              totals: {},
              total: 0
            };
          }

          const currentMonth = monthlyTotalsMap[monthKey];

          if (!currentMonth.totals[expense.category]) {
            currentMonth.totals[expense.category] = 0;
          }

          currentMonth.totals[expense.category] += expense.amount;
          currentMonth.total += expense.amount;
        });

        // Convert map to array
        const result = Object.values(monthlyTotalsMap)
          .sort((a, b) => a.month.localeCompare(b.month));

        setMonthlyTotals(result);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchMonthlyTotals();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (monthlyTotals.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No expenses found.</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Monthly Spending Totals</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
        {monthlyTotals.map((monthData) => (
          <div key={monthData.month} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
            <h2 style={{ margin: "0 0 10px 0", textAlign: "center" }}>
              {new Date(`${monthData.month}-01`).toLocaleString("default", { month: "long", year: "numeric" })}
            </h2>
            <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
              {Object.entries(monthData.totals).map(([category, total]) => (
                <div key={category} style={{ display: "flex", justifyContent: "space-between", padding: "5px 0" }}>
                  <span>{category}</span>
                  <span>${total.toFixed(2)}</span>
                </div>
              ))}
              <div style={{ borderTop: "1px solid #eee", paddingTop: "10px", fontWeight: "bold", display: "flex", justifyContent: "space-between" }}>
                <span>Total:</span>
                <span>${monthData.total.toFixed(2)}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

