  commentText: string,
  timestamp: string
): void {
  const stmt = db.prepare(
    "UPDATE comments SET photo_id = ?, author_id = ?, comment_text = ?, timestamp = ? WHERE id = ?"
  );
  stmt.run(photoId, authorId, commentText, timestamp, id);
}

export function deleteComment(id: number): void {
  const stmt = db.prepare("DELETE FROM comments WHERE id = ?");
  stmt.run(id);
}

