import type { Request, Response, NextFunction } from "express";
import { Router } from "express";
import { router as photosApiRouter } from "../routes/photos-api";
import { router as albumAccessServiceRouter } from "../routes/album-access-service";
import { router as commentServiceRouter } from "../routes/comment-service";
import { router as deleteGuardRouter } from "../routes/delete-guard";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check access for photo-related routes
  const photoRoutes = [
    '/photos',
    '/photos/:id',
    '/photos/:id/comments',
    '/photos/:id/delete'
  ];

  const isPhotoRoute = photoRoutes.some(route => 
    req.path === route || 
    (route.includes(':id') && req.path.startsWith(route.replace(':id', '')))
  );

  // Skip validation for non-photo routes
  if (!isPhotoRoute) {
    next();
    return;
  }

  // Check if user is a family member
  // This is a placeholder implementation - in reality this would
  // check session data, JWT tokens, or similar
  const isFamilyMember = req.headers['x-family-member'] === 'true';

  if (!isFamilyMember) {
    res.status(403).json({ error: 'Access denied: not a family member' });
    return;
  }

  next();
}

