import { useEffect, useState } from "react";

export function DeleteConfirmation() {
  const [photoId, setPhotoId] = useState<string | null>(null);
  const [photo, setPhoto] = useState<{ id: string; title: string } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [confirming, setConfirming] = useState(false);

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const id = urlParams.get("id");

    if (!id) {
      setError("No photo ID provided.");
      setLoading(false);
      return;
    }

    setPhotoId(id);

    fetch(`/api/photos-api/${id}`)
      .then(res => {
        if (!res.ok) throw new Error("Failed to fetch photo");
        return res.json();
      })
      .then(data => {
        setPhoto({ id: data.id, title: data.title });
        setLoading(false);
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, []);

  const handleDelete = () => {
    if (!photoId) return;

    setConfirming(true);

    fetch(`/api/photos-api/${photoId}`, { method: "DELETE" })
      .then(res => {
        if (!res.ok) throw new Error("Failed to delete photo");
        window.location.href = "/";
      })
      .catch(err => {
        setError(err.message);
        setConfirming(false);
      });
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
        <h1>Error</h1>
        <p>{error}</p>
      </div>
    );
  }

  if (!photo) {
    return (
      <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
        <h1>Photo Not Found</h1>
        <p>The requested photo could not be found.</p>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
      <h1>Delete Photo</h1>
      <p>Are you sure you want to delete the photo titled:</p>
      <div style={{ backgroundColor: "#f0f0f0", padding: "15px", borderRadius: "8px", marginBottom: "20px" }}>
        <strong>{photo.title}</strong>
      </div>
      <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
        <button 
          onClick={() => window.history.back()}
          style={{ flex: 1, minWidth: "120px", padding: "10px", backgroundColor: "#ccc", border: "none", borderRadius: "4px" }}
        >
          Cancel
        </button>
        <button 
          onClick={handleDelete}
          disabled={confirming}
          style={{ flex: 1, minWidth: "120px", padding: "10px", backgroundColor: "#d32f2f", color: "white", border: "none", borderRadius: "4px" }}
        >
          {confirming ? "Deleting..." : "Delete Photo"}
        </button>
      </div>
    </div>
  );
}

import { Router, type Request, type Response } from "express";
import { db as photosDb, getAllPhotos, getPhotoById, insertPhoto, updatePhoto, deletePhoto } from "../db/photos-table";
import { db as commentsDb, getAllComments, getCommentById, insertComment, updateComment, deleteComment } from "../db/comments-table";
import { middleware as albumAccessGuard } from "../middleware/album-access-guard";
import { middleware as ownerOnlyDeleteGuard } from "../middleware/owner-only-delete-guard";

export const router = Router();

// Get all photos
router.get("/", albumAccessGuard, (req: Request, res: Response) => {
  try {
    const photos = getAllPhotos();
    res.json(photos);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch photos" });
  }
});

// Get a specific photo by ID
router.get("/:id", albumAccessGuard, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid photo ID" });
    }

    const photo = getPhotoById(id);
    if (!photo) {
      return res.status(404).json({ error: "Photo not found" });
    }

    res.json(photo);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch photo" });
  }
});

// Create a new photo
router.post("/", (req: Request, res: Response) => {
  try {
    const { filename, owner_id } = req.body;

    if (!filename || !owner_id) {
      return res.status(400).json({ error: "Filename and owner_id are required" });
    }

    const newPhotoId = insertPhoto(filename, owner_id);
    const newPhoto = getPhotoById(newPhotoId);

    if (!newPhoto) {
      return res.status(500).json({ error: "Failed to retrieve created photo" });
    }

    res.status(201).json(newPhoto);
  } catch (error) {
    res.status(500).json({ error: "Failed to create photo" });
  }
});

// Update a photo
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { filename, owner_id } = req.body;

    if (isNaN(id) || !filename || !owner_id) {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const existingPhoto = getPhotoById(id);
    if (!existingPhoto) {
      return res.status(404).json({ error: "Photo not found" });
    }

    updatePhoto(id, filename, owner_id);
    const updatedPhoto = getPhotoById(id);

    if (!updatedPhoto) {
      return res.status(500).json({ error: "Failed to retrieve updated photo" });
    }

    res.json(updatedPhoto);
  } catch (error) {
    res.status(500).json({ error: "Failed to update photo" });
  }
});

// Delete a photo
router.delete("/:id", ownerOnlyDeleteGuard, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid photo ID" });
    }

    const existingPhoto = getPhotoById(id);
    if (!existingPhoto) {
      return res.status(404).json({ error: "Photo not found" });
    }

    deletePhoto(id);
    res.json({ message: "Photo deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete photo" });
  }
});

// Get all comments
router.get("/comments", (req: Request, res: Response) => {
  try {
    const comments = getAllComments();
    res.json(comments);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch comments" });
  }
});

// Get a specific comment by ID
router.get("/comments/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid comment ID" });
    }

    const comment = getCommentById(id);
    if (!comment) {
      return res.status(404).json({ error: "Comment not found" });
    }

    res.json(comment);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch comment" });
  }
});

// Create a new comment
router.post("/comments", (req: Request, res: Response) => {
  try {
    const { photoId, authorId, commentText, timestamp } = req.body;

    if (!photoId || !authorId || !commentText || !timestamp) {
      return res.status(400).json({ error: "photoId, authorId, commentText, and timestamp are required" });
    }

    const newCommentId = insertComment(photoId, authorId, commentText, timestamp);
    const newComment = getCommentById(newCommentId);

    if (!newComment) {
      return res.status(500).json({ error: "Failed to retrieve created comment" });
    }

    res.status(201).json(newComment);
  } catch (error) {
    res.status(500).json({ error: "Failed to create comment" });
  }
