              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <strong>{walk.date}</strong> at {walk.time} ({walk.duration} mins)
                  <br />
                  Status: {walk.status}
                </div>
                <div style={{ display: "flex", gap: "5px" }}>
                  {walk.status === "pending" && (
                    <>
                      <button
                        onClick={() => handleAccept(walk.id)}
                        style={{
                          backgroundColor: "#28a745",
                          color: "white",
                          border: "none",
                          padding: "5px 10px",
                          borderRadius: "4px",
                          cursor: "pointer",
                        }}
                      >
                        Accept
                      </button>
                      <button
                        onClick={() => handleDecline(walk.id)}
                        style={{
                          backgroundColor: "#dc3545",
                          color: "white",
                          border: "none",
                          padding: "5px 10px",
                          borderRadius: "4px",
                          cursor: "pointer",
                        }}
                      >
                        Decline
                      </button>
                    </>
                  )}
                  <button
                    onClick={() => handleDelete(walk.id)}
                    style={{
                      backgroundColor: "#6c757d",
                      color: "white",
                      border: "none",
                      padding: "5px 10px",
                      borderRadius: "4px",
                      cursor: "pointer",
                    }}
