} from "../db/reservations-table";

export const router = Router();

// Get all plots
router.get("/plots", (req: Request, res: Response) => {
  try {
    const plots = getAllPlots();
    res.json(plots);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch plots" });
  }
});

// Get a specific plot by ID
router.get("/plots/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const plot = getPlotById(id);
    if (!plot) {
      return res.status(404).json({ error: "Plot not found" });
    }
    res.json(plot);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch plot" });
  }
});

// Create a new plot
router.post("/plots", (req: Request, res: Response) => {
  try {
    const { location, size, status } = req.body;
    if (!location || !size || !status) {
      return res.status(400).json({ error: "Location, size, and status are required" });
    }
    const newPlotId = insertPlot({ location, size, status });
    const newPlot = getPlotById(newPlotId);
    if (!newPlot) {
      return res.status(500).json({ error: "Failed to retrieve created plot" });
    }
    res.status(201).json(newPlot);
  } catch (error) {
    res.status(500).json({ error: "Failed to create plot" });
  }
});

// Update a plot
router.put("/plots/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { location, size, status } = req.body;
    if (!location || !size || !status) {
      return res.status(400).json({ error: "Location, size, and status are required" });
    }
    const updated = updatePlot(id, { location, size, status });
    if (!updated) {
      return res.status(404).json({ error: "Plot not found" });
    }
    const updatedPlot = getPlotById(id);
    if (!updatedPlot) {
      return res.status(500).json({ error: "Failed to retrieve updated plot" });
    }
    res.json(updatedPlot);
  } catch (error) {
    res.status(500).json({ error: "Failed to update plot" });
  }
});

// Delete a plot
router.delete("/plots/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const deleted = deletePlot(id);
    if (!deleted) {
      return res.status(404).json({ error: "Plot not found" });
    }
    res.json({ message: "Plot deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete plot" });
  }
});

