import type { Request, Response, NextFunction } from "express";
import { router as gardenApiRouter } from "../routes/garden-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check reassignment for POST requests to the garden API routes
  if (req.method !== "POST" || !req.path.startsWith("/garden/")) {
    next();
    return;
  }

  // Check if coordinator flag is set on the actor
  // This is a placeholder implementation - in a real scenario,
  // you would check the request context or user session
  const isCoordinator = req.headers["x-coordinator"] === "true";

  if (!isCoordinator) {
    res.status(403).json({ error: "Reassignment not allowed: coordinator flag required" });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

interface Plot {
  id: number;
  name: string;
  size: string;
  location: string;
}

interface Reservation {
  id: number;
  plotId: number;
  memberId: number;
  startDate: string;
  endDate: string;
}

export function PlotReservationView() {
  const [plots, setPlots] = useState<Plot[]>([]);
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedPlotId, setSelectedPlotId] = useState<number | null>(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  useEffect(() => {
    async function fetchPlotsAndReservations() {
      try {
        const [plotsResponse, reservationsResponse] = await Promise.all([
          fetch("/api/garden-api/plots"),
          fetch("/api/garden-api/reservations"),
        ]);

        if (!plotsResponse.ok || !reservationsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const plotsData = await plotsResponse.json();
        const reservationsData = await reservationsResponse.json();

        setPlots(plotsData);
        setReservations(reservationsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchPlotsAndReservations();
  }, []);

  const handleReservePlot = async (plotId: number) => {
    if (!startDate || !endDate) {
      setError("Please enter both start and end dates.");
      return;
    }

    try {
      const response = await fetch("/api/garden-api/reservations", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          plotId,
          memberId: 1, // Assuming member ID 1 for now
          startDate,
          endDate,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to reserve plot");
      }

      // Refresh data after successful reservation
      const [plotsResponse, reservationsResponse] = await Promise.all([
        fetch("/api/garden-api/plots"),
        fetch("/api/garden-api/reservations"),
      ]);

      if (plotsResponse.ok && reservationsResponse.ok) {
        const plotsData = await plotsResponse.json();
        const reservationsData = await reservationsResponse.json();

        setPlots(plotsData);
        setReservations(reservationsData);
        setSelectedPlotId(null);
        setStartDate("");
        setEndDate("");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  const availablePlots = plots.filter(plot => {
    const isReserved = reservations.some(
      r => r.plotId === plot.id && r.endDate >= new Date().toISOString().split("T")[0]
    );
    return !isReserved;
  });

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Community Garden Plot Reservation</h1>

      {availablePlots.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>
          No plots available for reservation.
        </p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {availablePlots.map(plot => (
            <div
              key={plot.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                backgroundColor: "#f9f9f9",
              }}
            >
              <h3>{plot.name}</h3>
              <p><strong>Size:</strong> {plot.size}</p>
              <p><strong>Location:</strong> {plot.location}</p>

              {selectedPlotId === plot.id ? (
                <div style={{ marginTop: "10px" }}>
                  <input
                    type="date"
                    value={startDate}
                    onChange={e => setStartDate(e.target.value)}
                    placeholder="Start date"
                    style={{
                      width: "100%",
                      padding: "8px",
                      marginBottom: "10px",
                      borderRadius: "4px",
                      border: "1px solid #ddd",
                    }}
                  />
                  <input
                    type="date"
                    value={endDate}
                    onChange={e => setEndDate(e.target.value)}
                    placeholder="End date"
                    style={{
                      width: "100%",
                      padding: "8px",
                      marginBottom: "10px",
                      borderRadius: "4px",
                      border: "1px solid #ddd",
                    }}
                  />
                  <button
                    onClick={() => handleReservePlot(plot.id)}
                    style={{
                      backgroundColor: "#4CAF50",
                      color: "white",
                      border: "none",
                      padding: "10px 15px",
                      borderRadius: "4px",
                      cursor: "pointer",
                      width: "100%",
                    }}
                  >
                    Reserve Plot
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => setSelectedPlotId(plot.id)}
                  style={{
                    backgroundColor: "#2196F3",
                    color: "white",
                    border: "none",
                    padding: "10px 15px",
                    borderRadius: "4px",
                    cursor: "pointer",
                    width: "100%",
                  }}
                >
                  Reserve This Plot
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

