export function CoordinatorReassignmentPanel() {
  const [plots, setPlots] = useState<Plot[]>([]);
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedReservation, setSelectedReservation] = useState<number | null>(null);
  const [newPlotId, setNewPlotId] = useState<number | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [plotsResponse, reservationsResponse] = await Promise.all([
          fetch("/api/garden-api/plots"),
          fetch("/api/garden-api/reservations")
        ]);

        if (!plotsResponse.ok || !reservationsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const plotsData = await plotsResponse.json();
        const reservationsData = await reservationsResponse.json();

        setPlots(plotsData);
        setReservations(reservationsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleReassign = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedReservation === null || newPlotId === null) return;

    try {
      const response = await fetch(`/api/garden-api/reservations/${selectedReservation}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ plotId: newPlotId })
      });

      if (!response.ok) {
        throw new Error("Failed to reassign plot");
      }

      // Refresh data after successful reassignment
      const [plotsResponse, reservationsResponse] = await Promise.all([
        fetch("/api/garden-api/plots"),
        fetch("/api/garden-api/reservations")
      ]);

      if (!plotsResponse.ok || !reservationsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const plotsData = await plotsResponse.json();
      const reservationsData = await reservationsResponse.json();

      setPlots(plotsData);
      setReservations(reservationsData);
      setSelectedReservation(null);
      setNewPlotId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
