              <tr style={{ borderBottom: "1px solid #ccc" }}>
                <th style={{ textAlign: "left", padding: "8px" }}>Reserved By</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Plot Location</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Start Date</th>
                <th style={{ textAlign: "left", padding: "8px" }}>End Date</th>
              </tr>
            </thead>
            <tbody>
              {reservations.map(reservation => {
                const plot = plots.find(p => p.id === reservation.plotId);
                return (
                  <tr key={reservation.id} style={{ borderBottom: "1px solid #eee" }}>
                    <td style={{ padding: "8px" }}>{reservation.reservedBy}</td>
                    <td style={{ padding: "8px" }}>{plot?.location || "Unknown"}</td>
                    <td style={{ padding: "8px" }}>{reservation.startDate}</td>
                    <td style={{ padding: "8px" }}>{reservation.endDate}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      <div style={{ marginTop: "30px" }}>
        <h2>Reassign Plot</h2>
        <form onSubmit={handleReassign}>
          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="reservationSelect" style={{ display: "block", marginBottom: "5px" }}>
              Select Reservation:
            </label>
            <select
              id="reservationSelect"
              value={selectedReservation ?? ""}
              onChange={(e) => setSelectedReservation(Number(e.target.value))}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
              <option value="">-- Choose a reservation --</option>
              {reservations.map(reservation => (
                <option key={reservation.id} value={reservation.id}>
                  {reservation.reservedBy} - {reservation.startDate} to {reservation.endDate}
                </option>
              ))}
            </select>
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="plotSelect" style={{ display: "block", marginBottom: "5px" }}>
              Assign New Plot:
            </label>
            <select
              id="plotSelect"
              value={newPlotId ?? ""}
              onChange={(e) => setNewPlotId(Number(e.target.value))}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
              <option value="">-- Choose a plot --</option>
              {availablePlots.map(plot => (
                <option key={plot.id} value={plot.id}>
                  {plot.location} ({plot.size})
                </option>
              ))}
            </select>
          </div>

          <button
            type="submit"
            disabled={!selectedReservation || !newPlotId}
            style={{
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              padding: "10px 15px",
              borderRadius: "4px",
              cursor: "pointer",
              fontSize: "16px"
            }}
          >
            Reassign Plot
          </button>
        </form>
      </div>
    </div>
  );
}

