export const db = new DatabaseSync(":memory:");

interface Plot {
  id: number;
  status: "available" | "reserved";
  current_reservation: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS plots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    status TEXT NOT NULL,
    current_reservation TEXT
  )
`;

db.exec(createTableSql);

export function getAllPlots(): Plot[] {
  const stmt = db.prepare(`SELECT * FROM plots`);
  return stmt.all() as unknown as Plot[];
}

export function getPlotById(id: number): Plot | undefined {
  const stmt = db.prepare(`SELECT * FROM plots WHERE id = ?`);
  return stmt.get(id) as unknown as Plot | undefined;
}

export function insertPlot(plot: Omit<Plot, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO plots (status, current_reservation) VALUES (?, ?)`
  );
  const result = stmt.run(plot.status, plot.current_reservation);
  return Number(result.lastInsertRowid);
}

export function updatePlot(id: number, plot: Partial<Plot>): boolean {
  const stmt = db.prepare(
    `UPDATE plots SET status = ?, current_reservation = ? WHERE id = ?`
  );
  const result = stmt.run(
    plot.status ?? "",
    plot.current_reservation ?? null,
    id
  );
  return result.changes > 0;
}

export function deletePlot(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM plots WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

