import { Router, type Request, type Response } from "express";
import {
  db,
  deleteReservation,
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation
} from "../db/reservations-table";

export const router = Router();

// Get all reservations
router.get("/", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// Get a reservation by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  try {
    const { vendorId, stallNumber, weekendDate } = req.body;

    // Validate required fields
    if (!vendorId || !stallNumber || !weekendDate) {
      return res.status(400).json({
        error: "Missing required fields: vendorId, stallNumber, weekendDate"
      });
    }

    // Check if vendor already has a reservation
    const existingReservations = getAllReservations().filter(
      r => r.vendorId === vendorId
    );

    if (existingReservations.length > 0) {
      return res.status(400).json({
        error: "Vendor already has a reservation"
      });
    }

    const newId = insertReservation(vendorId, stallNumber, weekendDate);
    const newReservation = getReservationById(newId);

    if (!newReservation) {
      return res.status(500).json({ error: "Failed to create reservation" });
    }

    res.status(201).json(newReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// Update a reservation
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const { vendorId, stallNumber, weekendDate } = req.body;

    // Validate required fields
    if (!vendorId || !stallNumber || !weekendDate) {
      return res.status(400).json({
        error: "Missing required fields: vendorId, stallNumber, weekendDate"
      });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    updateReservation(id, vendorId, stallNumber, weekendDate);
    const updatedReservation = getReservationById(id);

    if (!updatedReservation) {
      return res.status(500).json({ error: "Failed to update reservation" });
    }

    res.json(updatedReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reservation" });
  }
});

// Delete a reservation (only managers can cancel)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    // Only allow managers to cancel (we'll assume any deletion is by manager)
    deleteReservation(id);
    res.json({ message: "Reservation cancelled successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to cancel reservation" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { router as reservationsRouter } from "../routes/reservations-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check cancellation requests
  if (req.method !== "DELETE" || !req.path.startsWith("/reservations/")) {
    next();
    return;
  }

  // Check if user is manager
  // This is a placeholder - in reality, you'd check auth headers/token
  // For now, we'll assume a manager flag is present in request
  const isManager = req.headers["x-user-role"] === "manager";

  if (!isManager) {
    res.status(403).json({ error: "Cancellation restricted to managers" });
    return;
  }

  next();
}

