}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS workouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    clientId INTEGER NOT NULL,
    date TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllWorkouts(): Workout[] {
  const stmt = db.prepare(`SELECT * FROM workouts`);
  return stmt.all() as unknown as Workout[];
}

export function getWorkoutById(id: number): Workout | undefined {
  const stmt = db.prepare(`SELECT * FROM workouts WHERE id = ?`);
  return stmt.get(id) as unknown as Workout | undefined;
}

export function insertWorkout(clientId: number, date: string): number {
  const stmt = db.prepare(
    `INSERT INTO workouts (clientId, date) VALUES (?, ?)`
  );
  const result = stmt.run(clientId, date);
  return Number(result.lastInsertRowid);
}

export function updateWorkout(
  id: number,
  clientId: number,
  date: string
): void {
  const stmt = db.prepare(
    `UPDATE workouts SET clientId = ?, date = ? WHERE id = ?`
  );
  stmt.run(clientId, date, id);
}

export function deleteWorkout(id: number): void {
  const stmt = db.prepare(`DELETE FROM workouts WHERE id = ?`);
  stmt.run(id);
}

