import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./trainer-client.db");

interface ClientTrainerRow {
  client_id: number;
  trainer_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS client_trainer (
    client_id INTEGER NOT NULL,
    trainer_id INTEGER NOT NULL,
    PRIMARY KEY (client_id, trainer_id),
    FOREIGN KEY (client_id) REFERENCES clients(id),
    FOREIGN KEY (trainer_id) REFERENCES trainers(id)
  )
`;

db.exec(createTableSql);

export function getAllClientTrainers(): ClientTrainerRow[] {
  const stmt = db.prepare("SELECT * FROM client_trainer");
  return stmt.all() as unknown as ClientTrainerRow[];
}

export function getClientTrainerById(clientId: number, trainerId: number): ClientTrainerRow | undefined {
  const stmt = db.prepare(
    "SELECT * FROM client_trainer WHERE client_id = ? AND trainer_id = ?"
  );
  return stmt.get(clientId, trainerId) as ClientTrainerRow | undefined;
}

export function insertClientTrainer(clientId: number, trainerId: number): number {
  const stmt = db.prepare(
    "INSERT INTO client_trainer (client_id, trainer_id) VALUES (?, ?)"
  );
  const result = stmt.run(clientId, trainerId);
  return Number(result.lastInsertRowid);
}

export function updateClientTrainer(
  clientId: number,
  trainerId: number,
  newTrainerId: number
): boolean {
  const stmt = db.prepare(
    "UPDATE client_trainer SET trainer_id = ? WHERE client_id = ? AND trainer_id = ?"
  );
  const result = stmt.run(newTrainerId, clientId, trainerId);
  return result.changes > 0;
}

export function deleteClientTrainer(clientId: number, trainerId: number): boolean {
  const stmt = db.prepare(
    "DELETE FROM client_trainer WHERE client_id = ? AND trainer_id = ?"
  );
  const result = stmt.run(clientId, trainerId);
  return result.changes > 0;
}

