import { Router, type Request, type Response } from "express";
import { 
  getAllWorkouts,
  getWorkoutById,
  insertWorkout,
  updateWorkout,
  deleteWorkout
} from "../db/workouts-table";
import { 
  getAllClientTrainers,
  getClientTrainerById
} from "../db/client-trainer-table";

export const router = Router();

// Get all workouts for the logged-in trainer
router.get("/", (req: Request, res: Response) => {
  try {
    const workouts = getAllWorkouts();
    return res.json(workouts);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch workouts" });
  }
});

// Get a specific workout by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid workout ID" });
  }

  const workout = getWorkoutById(id);

  if (!workout) {
    return res.status(404).json({ error: "Workout not found" });
  }

  return res.json(workout);
});

// Create a new workout
router.post("/", (req: Request, res: Response) => {
  const { clientId, date } = req.body;

  if (!clientId || !date) {
    return res.status(400).json({ error: "Client ID and date are required" });
  }

  const clientIdNum = Number(clientId);

  if (isNaN(clientIdNum)) {
    return res.status(400).json({ error: "Invalid client ID" });
  }

  // Verify that the client belongs to the trainer
  const clientTrainer = getClientTrainerById(clientIdNum, 1); // Assuming trainer ID is 1

  if (!clientTrainer) {
    return res.status(400).json({ error: "Client does not belong to trainer" });
  }

  try {
    const newId = insertWorkout(clientIdNum, date);
    const newWorkout = getWorkoutById(newId);

    if (!newWorkout) {
      return res.status(500).json({ error: "Failed to create workout" });
    }

    return res.status(201).json(newWorkout);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create workout" });
  }
});

// Update a workout
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { clientId, date } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid workout ID" });
  }

  if (!clientId || !date) {
    return res.status(400).json({ error: "Client ID and date are required" });
  }

  const clientIdNum = Number(clientId);

  if (isNaN(clientIdNum)) {
    return res.status(400).json({ error: "Invalid client ID" });
  }

  const existingWorkout = getWorkoutById(id);

  if (!existingWorkout) {
    return res.status(404).json({ error: "Workout not found" });
  }

  try {
    updateWorkout(id, clientIdNum, date);
    const updatedWorkout = getWorkoutById(id);

    if (!updatedWorkout) {
      return res.status(500).json({ error: "Failed to update workout" });
    }

    return res.json(updatedWorkout);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update workout" });
  }
});

// Delete a workout
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid workout ID" });
  }

  const existingWorkout = getWorkoutById(id);

  if (!existingWorkout) {
    return res.status(404).json({ error: "Workout not found" });
  }

  try {
    deleteWorkout(id);
    return res.json({ message: "Workout deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete workout" });
  }
});

