const checkClientOwnership = (req: Request, res: Response, next: () => void) => {
  // Extract client ID from URL params
  const clientId = Number(req.params.clientId);

  // Extract trainer ID from request (assuming it's in req.user.id)
  // Note: In a real app, you'd have proper authentication middleware
  // that populates req.user with trainer info
  const trainerId = Number(req.headers.trainerid);

  // If either ID is invalid, return 400
  if (isNaN(clientId) || isNaN(trainerId)) {
    return res.status(400).json({ error: "Invalid client or trainer ID" });
  }

  // Check if the trainer owns the client
  const clientTrainer = getClientTrainerById(clientId, trainerId);

  if (!clientTrainer) {
    return res.status(403).json({ error: "Trainer does not own this client" });
  }

  // If ownership is confirmed, proceed to next middleware/route handler
  next();
};

// Apply the ownership check middleware to all routes that require it
router.use("/:clientId", checkClientOwnership);

// Example route that requires ownership check
router.put("/:clientId", (req: Request, res: Response) => {
  // This route would normally update client data
  // But since we're just checking ownership, we'll return a simple response
  return res.json({ message: "Client ownership verified" });
});

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./petboarding.db");

interface PetRow {
  id: number;
  species: string;
  owner_contact: string;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS pets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    species TEXT NOT NULL,
    owner_contact TEXT NOT NULL,
    status TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllPets(): PetRow[] {
  const stmt = db.prepare("SELECT * FROM pets");
  return stmt.all() as unknown as PetRow[];
}

export function getPetById(id: number): PetRow | undefined {
  const stmt = db.prepare("SELECT * FROM pets WHERE id = ?");
  return stmt.get(id) as unknown as PetRow | undefined;
}

export function insertPet(pet: Omit<PetRow, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO pets (species, owner_contact, status) VALUES (?, ?, ?)"
  );
  const result = stmt.run(pet.species, pet.owner_contact, pet.status);
  return Number(result.lastInsertRowid);
}

export function updatePet(id: number, pet: Partial<Omit<PetRow, "id">>): boolean {
  const fields = [];
  const values = [];

  if (pet.species !== undefined) {
    fields.push("species = ?");
    values.push(pet.species);
  }

  if (pet.owner_contact !== undefined) {
    fields.push("owner_contact = ?");
    values.push(pet.owner_contact);
  }

  if (pet.status !== undefined) {
    fields.push("status = ?");
    values.push(pet.status);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE pets SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deletePet(id: number): boolean {
  const stmt = db.prepare("DELETE FROM pets WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

