import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./petboarding.db");

const createTableSQL = `
  CREATE TABLE IF NOT EXISTS billing_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    pet_id INTEGER NOT NULL,
    stay_duration INTEGER NOT NULL,
    calculated_cost REAL NOT NULL
  )
`;

db.exec(createTableSQL);

export interface BillingRecord {
  id: number;
  pet_id: number;
  stay_duration: number;
  calculated_cost: number;
}

export function getAllBillingRecords(): BillingRecord[] {
  const stmt = db.prepare(`SELECT * FROM billing_records`);
  return stmt.all() as unknown as BillingRecord[];
}

export function getBillingRecordById(id: number): BillingRecord | undefined {
  const stmt = db.prepare(`SELECT * FROM billing_records WHERE id = ?`);
  return stmt.get(id) as unknown as BillingRecord | undefined;
}

export function insertBillingRecord(
  petId: number,
  stayDuration: number,
  calculatedCost: number
): number {
  const stmt = db.prepare(
    `INSERT INTO billing_records (pet_id, stay_duration, calculated_cost) VALUES (?, ?, ?)`
  );
  const result = stmt.run(petId, stayDuration, calculatedCost);
  return Number(result.lastInsertRowid);
}

export function updateBillingRecord(
  id: number,
  petId: number,
  stayDuration: number,
  calculatedCost: number
): number {
  const stmt = db.prepare(
    `UPDATE billing_records SET pet_id = ?, stay_duration = ?, calculated_cost = ? WHERE id = ?`
  );
  const result = stmt.run(petId, stayDuration, calculatedCost, id);
  return Number(result.changes);
}

export function deleteBillingRecord(id: number): number {
  const stmt = db.prepare(`DELETE FROM billing_records WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
}

