import { Router, type Request, type Response } from "express";
import {
  getAllPets,
  getPetById,
  insertPet,
  updatePet,
  deletePet
} from "../db/pets-table";
import {
  getAllBillingRecords,
  getBillingRecordById,
  insertBillingRecord,
  updateBillingRecord,
  deleteBillingRecord
} from "../db/billing-records-table";

export const router = Router();

// GET /pets - Get all pets
router.get("/pets", (req: Request, res: Response) => {
  try {
    const pets = getAllPets();
    res.json(pets);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch pets" });
  }
});

// GET /pets/:id - Get a specific pet by ID
router.get("/pets/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid pet ID" });
    }

    const pet = getPetById(id);
    if (!pet) {
      return res.status(404).json({ error: "Pet not found" });
    }

    res.json(pet);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch pet" });
  }
});

// POST /pets - Create a new pet
router.post("/pets", (req: Request, res: Response) => {
  try {
    const { name, breed, check_in_date, check_out_date } = req.body;

    if (!name || !breed || !check_in_date) {
      return res.status(400).json({ error: "Name, breed, and check-in date are required" });
    }

    const newPetId = insertPet({
      name,
      breed,
      check_in_date,
      check_out_date: check_out_date || null
    });

    const createdPet = getPetById(newPetId);
    if (!createdPet) {
      return res.status(500).json({ error: "Failed to retrieve created pet" });
    }

    res.status(201).json(createdPet);
  } catch (error) {
    res.status(500).json({ error: "Failed to create pet" });
  }
});

// PUT /pets/:id - Update a pet
router.put("/pets/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid pet ID" });
    }

    const pet = getPetById(id);
    if (!pet) {
      return res.status(404).json({ error: "Pet not found" });
    }

    const { name, breed, check_in_date, check_out_date } = req.body;

    const updated = updatePet(id, {
      name: name ?? pet.name,
      breed: breed ?? pet.breed,
      check_in_date: check_in_date ?? pet.check_in_date,
      check_out_date: check_out_date ?? pet.check_out_date
    });

    if (!updated) {
      return res.status(500).json({ error: "Failed to update pet" });
    }

    const updatedPet = getPetById(id);
    res.json(updatedPet);
  } catch (error) {
    res.status(500).json({ error: "Failed to update pet" });
  }
});

// DELETE /pets/:id - Delete a pet
router.delete("/pets/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid pet ID" });
    }

    const deleted = deletePet(id);
    if (!deleted) {
      return res.status(404).json({ error: "Pet not found" });
    }

    res.json({ message: "Pet deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete pet" });
  }
});

