                    style={{ 
                      backgroundColor: "#dc3545", 
                      color: "white", 
                      padding: "5px 10px", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Check Out
                  </button>
                </div>
              </div>
            ))}
        </div>
      )}

      <h2 style={{ textAlign: "center", marginTop: "30px" }}>Checked Out Pets</h2>

      {pets.length === 0 ? (
