import { useEffect, useState } from "react";

interface BillingRecord {
  id: string;
  petId: string;
  amount: number;
  date: string;
  description: string;
}

export function BillingHistoryView() {
  const [billingRecords, setBillingRecords] = useState<BillingRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchBillingHistory() {
      try {
        const response = await fetch("/api/pets-api/billing");
        if (!response.ok) {
          throw new Error(`Failed to fetch billing history: ${response.status}`);
        }
        const records = await response.json();
        setBillingRecords(records);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchBillingHistory();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (billingRecords.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No billing history found.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px" }}>
      <h1>Billing History</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        {billingRecords.map((record) => (
          <div
            key={record.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              backgroundColor: "#f9f9f9",
            }}
          >
            <div style={{ fontWeight: "bold" }}>
              Amount: ${record.amount.toFixed(2)}
            </div>
            <div>Date: {new Date(record.date).toLocaleDateString()}</div>
            <div>Description: {record.description}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

