export function RoomBookingView() {
  const [rooms, setRooms] = useState<Room[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedRoomId, setSelectedRoomId] = useState<number | null>(null);
  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  useEffect(() => {
    fetchRooms();
    fetchBookings();
  }, []);

  const fetchRooms = async () => {
    try {
      const response = await fetch("/api/rooms-api/");
      if (!response.ok) throw new Error("Failed to fetch rooms");
      const data = await response.json();
      setRooms(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const fetchBookings = async () => {
    try {
      const response = await fetch("/api/rooms-api/");
      if (!response.ok) throw new Error("Failed to fetch bookings");
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleBookRoom = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedRoomId || !startTime || !endTime) return;

    try {
      const response = await fetch("/api/rooms-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          roomId: selectedRoomId,
          memberId: 1, // Assuming current member ID is 1
          startTime,
          endTime,
        }),
      });

      if (!response.ok) throw new Error("Failed to book room");

      // Reset form
      setSelectedRoomId(null);
      setStartTime("");
      setEndTime("");

      // Refresh data
      await fetchRooms();
      await fetchBookings();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center" }}>{error}</div>;

  return (
    <div style={{ maxWidth: 800, margin: "0 auto", padding: 20, fontFamily: "system-ui, sans-serif" }}>
      <h1>Room Booking</h1>

      <form onSubmit={handleBookRoom} style={{ marginBottom: 30 }}>
        <h2>Book a Room</h2>
        <div style={{ marginBottom: 10 }}>
          <label htmlFor="roomSelect">Select Room:</label>
          <select
            id="roomSelect"
            value={selectedRoomId || ""}
            onChange={(e) => setSelectedRoomId(Number(e.target.value))}
            style={{ width: "100%", padding: 8, borderRadius: 4 }}
          >
            <option value="">Choose a room</option>
            {rooms.map((room) => (
              <option key={room.id} value={room.id}>
                {room.name}
              </option>
            ))}
          </select>
        </div>

        <div style={{ marginBottom: 10 }}>
          <label htmlFor="startTime">Start Time:</label>
          <input
            type="datetime-local"
            id="startTime"
            value={startTime}
            onChange={(e) => setStartTime(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4 }}
          />
        </div>

        <div style={{ marginBottom: 10 }}>
          <label htmlFor="endTime">End Time:</label>
          <input
            type="datetime-local"
            id="endTime"
            value={endTime}
            onChange={(e) => setEndTime(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4 }}
          />
        </div>

        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            padding: "10px 20px",
            borderRadius: 4,
            cursor: "pointer",
          }}
        >
          Book Room
        </button>
      </form>

      <h2>Available Rooms</h2>
      {rooms.length === 0 ? (
        <p>No rooms available.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 20 }}>
          {rooms.map((room) => (
            <div
              key={room.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: 8,
                padding: 15,
                width: "calc(50% - 10px)",
                boxSizing: "border-box",
              }}
            >
              <h3>{room.name}</h3>
              <p>Capacity: {room.capacity}</p>
              <p>Equipment: {room.equipment.join(", ")}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

