import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

const createTableSql = `
  CREATE TABLE IF NOT EXISTS expenses (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    club_id INTEGER NOT NULL,
    member_id INTEGER NOT NULL,
    amount REAL NOT NULL,
    description TEXT NOT NULL,
    approved BOOLEAN NOT NULL
  )
`;

db.exec(createTableSql);

export interface ExpenseRow {
  id: number;
  club_id: number;
  member_id: number;
  amount: number;
  description: string;
  approved: boolean;
}

export function getAllExpenses(): ExpenseRow[] {
  const stmt = db.prepare(`SELECT * FROM expenses`);
  return stmt.all() as unknown as ExpenseRow[];
}

export function getExpenseById(id: number): ExpenseRow | undefined {
  const stmt = db.prepare(`SELECT * FROM expenses WHERE id = ?`);
  return stmt.get(id) as unknown as ExpenseRow | undefined;
}

export function insertExpense(
  clubId: number,
  memberId: number,
  amount: number,
  description: string,
  approved: boolean
): number {
  const stmt = db.prepare(
    `INSERT INTO expenses (club_id, member_id, amount, description, approved) VALUES (?, ?, ?, ?, ?)`
  );
  const result = stmt.run(clubId, memberId, amount, description, approved);
  return Number(result.lastInsertRowid);
}

export function updateExpense(
  id: number,
  clubId: number,
  memberId: number,
  amount: number,
  description: string,
  approved: boolean
): void {
  const stmt = db.prepare(
    `UPDATE expenses SET club_id = ?, member_id = ?, amount = ?, description = ?, approved = ? WHERE id = ?`
  );
  stmt.run(clubId, memberId, amount, description, approved, id);
}

export function deleteExpense(id: number): void {
  const stmt = db.prepare(`DELETE FROM expenses WHERE id = ?`);
  stmt.run(id);
}

