import { Router, type Request, type Response } from "express";
import { db, deleteExpense, getAllExpenses, getExpenseById, insertExpense, updateExpense } from "../db/expenses-table";

export const router = Router();

// Get all expenses
router.get("/", (req: Request, res: Response) => {
  try {
    const expenses = getAllExpenses();
    res.json(expenses);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch expenses" });
  }
});

// Get expense by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const expense = getExpenseById(id);
    if (!expense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    res.json(expense);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch expense" });
  }
});

// Create new expense
router.post("/", (req: Request, res: Response) => {
  try {
    const { clubId, memberId, amount, description, approved } = req.body;

    if (typeof clubId !== "number" || typeof memberId !== "number" || typeof amount !== "number" || typeof description !== "string" || typeof approved !== "boolean") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const newId = insertExpense(clubId, memberId, amount, description, approved);
    const createdExpense = getExpenseById(newId);

    if (!createdExpense) {
      return res.status(500).json({ error: "Failed to create expense" });
    }

    res.status(201).json(createdExpense);
  } catch (error) {
    res.status(500).json({ error: "Failed to create expense" });
  }
});

// Update expense
