  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const { clubId, memberId, amount, description, approved } = req.body;

    if (typeof clubId !== "number" || typeof memberId !== "number" || typeof amount !== "number" || typeof description !== "string" || typeof approved !== "boolean") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const existingExpense = getExpenseById(id);
    if (!existingExpense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    updateExpense(id, clubId, memberId, amount, description, approved);
    const updatedExpense = getExpenseById(id);

    if (!updatedExpense) {
