import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check approval requests
  if (!(req.method === "POST" && req.path === "/payouts/approve")) {
    next();
    return;
  }

  // Check if user has treasurer role
  const userRole = req.headers["x-user-role"];
  if (userRole !== "treasurer") {
    res.status(403).json({ error: "Forbidden: Only treasurer can approve payouts" });
    return;
  }

  next();
}

