    if (!consignment) {
      return res.status(404).json({ error: "Consignment not found" });
    }

    res.json(consignment);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch consignment" });
  }
});

// Create a new consignment
router.post("/", (req: Request, res: Response) => {
  try {
    const { title, price, sellerId, payoutStatus } = req.body;

    if (!title || typeof price !== "number" || !sellerId || !payoutStatus) {
      return res.status(400).json({
        error: "Title, price, sellerId, and payoutStatus are required"
      });
    }

    const id = insertConsignment(title, price, sellerId, payoutStatus);
    res.status(201).json({ id, title, price, sellerId, payoutStatus });
  } catch (error) {
    res.status(500).json({ error: "Failed to create consignment" });
  }
});

// Update an existing consignment
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID" });
    }

    const { title, price, sellerId, payoutStatus } = req.body;

    if (!title || typeof price !== "number" || !sellerId || !payoutStatus) {
      return res.status(400).json({
        error: "Title, price, sellerId, and payoutStatus are required"
      });
    }

    const existing = getConsignmentById(id);
    if (!existing) {
      return res.status(404).json({ error: "Consignment not found" });
    }

    updateConsignment(id, title, price, sellerId, payoutStatus);
    res.json({ id, title, price, sellerId, payoutStatus });
  } catch (error) {
    res.status(500).json({ error: "Failed to update consignment" });
  }
});

// Delete a consignment
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID" });
    }

    const existing = getConsignmentById(id);
    if (!existing) {
      return res.status(404).json({ error: "Consignment not found" });
