    res.status(500).json({ error: "Failed to delete consignment" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process payout-related requests
  if (!(req.method === "POST" && req.path === "/payouts")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Decode base64url
  const decodeBase64Url = (str: string): Buffer => {
    let base64 = str.replace(/-/g, "+").replace(/_/g, "/");
    const padding = 4 - (base64.length % 4);
    if (padding !== 4) {
      base64 += "=".repeat(padding);
    }
    return Buffer.from(base64, "base64");
  };

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest();

  const actualSignature = decodeBase64Url(signature);

  try {
    if (timingSafeEqual(expectedSignature, actualSignature)) {
      // Token is valid, check if staff
      const decodedPayload = JSON.parse(
        decodeBase64Url(payload).toString()
      );

      if (decodedPayload.role === "staff") {
        next();
      } else {
        res.status(403).json({ error: "Access denied" });
      }
    } else {
      res.status(401).json({ error: "Invalid token" });
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}

