export function StaffOnlyPayoutQueue() {
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBooks();
  }, []);

  const fetchBooks = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/books-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch books: ${response.status}`);
      }
      const data = await response.json();
      setBooks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleApprovePayout = async (id: number) => {
    try {
      const response = await fetch(`/api/books-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "pending_payout" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update book: ${response.status}`);
      }

      // Refresh the list after successful update
      await fetchBooks();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
