export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check requests to the co-op allocation API routes
  if (!req.path.startsWith("/api/allocation")) {
    next();
    return;
  }

  // Only check POST, PUT, DELETE methods
  if (req.method !== "POST" && req.method !== "PUT" && req.method !== "DELETE") {
    next();
    return;
  }

