        throw new Error(`Failed to add member: ${response.status} ${response.statusText}`);
      }

      setNewMember({ name: "", email: "", allocation: "" });
      fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const updateMember = async (id: string, allocation: number) => {
    try {
      const response = await fetch(`/api/co-op-allocation-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ allocation })
      });

      if (!response.ok) {
        throw new Error(`Failed to update member: ${response.status} ${response.statusText}`);
      }

      fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const deleteMember = async (id: string) => {
    try {
      const response = await fetch(`/api/co-op-allocation-api/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete member: ${response.status} ${response.statusText}`);
      }

      fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
