import { Router, type Request, type Response } from "express";
import { getRouteById } from "../db/routes-table";
import { getRoleRestrictionById } from "../db/role-restrictions-table";

export const router = Router();

// Middleware to check if user can retire a route
const roleCheckGuard = (req: Request, res: Response, next: () => void) => {
  const routeId = Number(req.params.id);
  const userId = Number(req.body.userId);

  // Validate inputs
  if (isNaN(routeId) || isNaN(userId)) {
    return res.status(400).json({ error: "Invalid route ID or user ID" });
  }

  // Get the route to check if it exists
  const route = getRouteById(routeId);
  if (!route) {
    return res.status(404).json({ error: "Route not found" });
  }

  // Get the user's role restriction
  const roleRestriction = getRoleRestrictionById(userId);
  if (!roleRestriction) {
    return res.status(404).json({ error: "User role restriction not found" });
  }

  // Allow retirement if user is head setter
  if (roleRestriction.role === "head setter") {
    next();
    return;
  }

  // Reject retirement if user is not head setter
  return res.status(403).json({ error: "Only head setters can retire routes" });
};

export { roleCheckGuard };

import type { Request, Response, NextFunction } from "express";
import { roleCheckGuard } from "../routes/role-check-guard";
import { router as routesRouter } from "../routes/routes-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check retirement requests
  if (!(req.method === "PUT" && req.path.startsWith("/api/routes/"))) {
    return next();
  }

  // Check if the request is to retire a route
  const isRetirementRequest = req.body && typeof req.body.retired === "boolean" && req.body.retired === true;

  if (!isRetirementRequest) {
    return next();
  }

  // Apply role check guard for retirement
  roleCheckGuard(req, res, next);
}

