      setNewRoute({ name: '', description: '', setter: '' });
      fetchRoutes();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleRetireRoute = async (id: number) => {
    try {
      const response = await fetch(`/api/routes-api/routes/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'retired' }),
      });
      if (!response.ok) {
        throw new Error(`Failed to retire route: ${response.status}`);
      }
      fetchRoutes();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteRoute = async (id: number) => {
    try {
      const response = await fetch(`/api/routes-api/routes/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete route: ${response.status}`);
      }
      fetchRoutes();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Route Log Board</h1>

      <div style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Create New Route</h2>
        <form onSubmit={handleCreateRoute}>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              placeholder="Route Name"
              value={newRoute.name}
              onChange={(e) => setNewRoute({...newRoute, name: e.target.value})}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              placeholder="Description"
              value={newRoute.description}
              onChange={(e) => setNewRoute({...newRoute, description: e.target.value})}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              placeholder="Setter Name"
              value={newRoute.setter}
              onChange={(e) => setNewRoute({...newRoute, setter: e.target.value})}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <button type="submit" style={{ padding: '10px 20px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
            Add Route
          </button>
        </form>
      </div>

      <h2>Current Routes</h2>
      {routes.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No routes found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {routes.map(route => (
            <div key={route.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <h3>{route.name}</h3>
                  <p>{route.description}</p>
                  <p><strong>Setter:</strong> {route.setter}</p>
                  <p><strong>Status:</strong> {route.status}</p>
                </div>
                <div style={{ display: 'flex', gap: '10px' }}>
                  {route.status === 'active' && (
                    <button 
                      onClick={() => handleRetireRoute(route.id)}
                      style={{ padding: '6px 12px', backgroundColor: '#ffc107', color: 'black', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                    >
                      Retire
                    </button>
                  )}
                  <button 
                    onClick={() => handleDeleteRoute(route.id)}
                    style={{ padding: '6px 12px', backgroundColor: '#dc3545', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Route {
  id: string;
  name: string;
  description: string;
  status: "active" | "retired";
}

export function RouteRetireConfirmation() {
  const [routes, setRoutes] = useState<Route[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedRouteId, setSelectedRouteId] = useState<string | null>(null);
  const [confirmation, setConfirmation] = useState(false);

  useEffect(() => {
    fetchRoutes();
  }, []);

  const fetchRoutes = async () => {
    try {
      const response = await fetch("/api/routes-api/routes");
      if (!response.ok) {
        throw new Error(`Failed to fetch routes: ${response.status}`);
      }
      const data = await response.json();
      setRoutes(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleRetireRoute = async (routeId: string) => {
    if (!confirmation) {
      setSelectedRouteId(routeId);
      return;
    }

    try {
      const response = await fetch(`/api/routes-api/routes/${routeId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "retired" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to retire route: ${response.status}`);
      }

      // Refresh the route list after retirement
      await fetchRoutes();
      setSelectedRouteId(null);
      setConfirmation(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  if (routes.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No routes found.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1>Route Retire Confirmation</h1>
      <p>Confirm retiring a route.</p>

      <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: "20px" }}>
        <thead>
          <tr style={{ borderBottom: "1px solid #ccc" }}>
            <th style={{ textAlign: "left", padding: "10px" }}>Name</th>
            <th style={{ textAlign: "left", padding: "10px" }}>Description</th>
            <th style={{ textAlign: "left", padding: "10px" }}>Status</th>
            <th style={{ textAlign: "left", padding: "10px" }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {routes.map((route) => (
            <tr key={route.id} style={{ borderBottom: "1px solid #eee" }}>
              <td style={{ padding: "10px" }}>{route.name}</td>
              <td style={{ padding: "10px" }}>{route.description}</td>
              <td style={{ padding: "10px" }}>{route.status}</td>
              <td style={{ padding: "10px" }}>
                {route.status === "active" && (
                  <button
                    onClick={() => handleRetireRoute(route.id)}
                    style={{
                      backgroundColor: "#dc3545",
                      color: "white",
                      border: "none",
                      borderRadius: "4px",
                      padding: "8px 12px",
                      cursor: "pointer",
                    }}
                  >
                    {selectedRouteId === route.id && !confirmation
                      ? "Confirm Retire"
                      : "Retire"}
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {selectedRouteId && !confirmation && (
        <div style={{ marginTop: "20px", padding: "10px", backgroundColor: "#f8f9fa", borderRadius: "4px" }}>
          <p>Are you sure you want to retire this route?</p>
          <button
            onClick={() => setConfirmation(true)}
            style={{
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              borderRadius: "4px",
              padding: "8px 12px",
              marginRight: "10px",
              cursor: "pointer",
            }}
          >
            Yes, Retire
          </button>
          <button
            onClick={() => {
              setSelectedRouteId(null);
              setConfirmation(false);
            }}
            style={{
              backgroundColor: "#6c757d",
              color: "white",
              border: "none",
              borderRadius: "4px",
              padding: "8px 12px",
              cursor: "pointer",
            }}
          >
            Cancel
          </button>
        </div>
      )}
    </div>
  );
}

