import { Router, type Request, type Response } from "express";
import { 
  getAllBookings,
  getBookingById,
  insertBooking,
  updateBooking,
  deleteBooking
} from "../db/bookings-table";

const router = Router();

// GET /bookings - Get all bookings
router.get("/bookings", (req: Request, res: Response) => {
  try {
    const bookings = getAllBookings();
    res.json(bookings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch bookings" });
  }
});

// GET /bookings/:id - Get a booking by ID
router.get("/bookings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    res.json(booking);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch booking" });
  }
});

// POST /bookings - Create a new booking
router.post("/bookings", (req: Request, res: Response) => {
  try {
    const { memberId, slotTime, endTime } = req.body;

    if (!memberId || !slotTime || !endTime) {
      return res.status(400).json({ error: "Member ID, slot time, and end time are required" });
    }

    const newId = insertBooking(memberId, slotTime, endTime);
    const createdBooking = getBookingById(newId);

    if (!createdBooking) {
      return res.status(500).json({ error: "Failed to create booking" });
    }

    res.status(201).json(createdBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to create booking" });
  }
});

// PUT /bookings/:id - Update a booking
router.put("/bookings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const { memberId, slotTime, endTime } = req.body;

    if (!memberId || !slotTime || !endTime) {
      return res.status(400).json({ error: "Member ID, slot time, and end time are required" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    updateBooking(id, memberId, slotTime, endTime);
    const updatedBooking = getBookingById(id);

    if (!updatedBooking) {
      return res.status(500).json({ error: "Failed to update booking" });
    }

    res.json(updatedBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to update booking" });
  }
});

// DELETE /bookings/:id - Delete a booking
router.delete("/bookings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    deleteBooking(id);
    res.json({ message: "Booking deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete booking" });
  }
});

