import { getBookingById, updateBooking } from "../db/bookings-table";
import { getStaffUserById } from "../db/staff-users-table";
import { middleware as staffOnlyGuard } from "../middleware/staff-only-extension-guard";
import { middleware as overlapChecker } from "../middleware/booking-overlap-checker";

export const router = Router();

router.put(
  "/:id/extend",
  staffOnlyGuard,
  overlapChecker,
  (req: Request, res: Response) => {
    const bookingId = Number(req.params.id);
    const { endTime } = req.body;

    if (!endTime) {
      return res.status(400).json({ error: "End time is required" });
    }

    const booking = getBookingById(bookingId);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    const staffUser = getStaffUserById(booking.member_id);
    if (!staffUser || !staffUser.isStaff) {
      return res.status(403).json({ error: "Access denied" });
    }

    updateBooking(bookingId, booking.member_id, booking.slot_time, endTime);
    return res.json({ message: "Booking extended successfully" });
  }
);

import type { Request, Response, NextFunction } from "express";
import { router as bookingsRouter } from "../routes/bookings-api";
import { router as staffExtensionRouter } from "../routes/staff-extension-endpoint";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check extension requests
  if (req.method !== "POST" || !req.path.startsWith("/api/extensions")) {
    next();
    return;
  }

  // Check if user is staff
  const isStaff = req.headers["x-user-role"] === "staff";

  if (!isStaff) {
    res.status(403).json({ error: "Access denied. Staff only." });
    return;
  }

  next();
}

