import { useEffect, useState } from "react";

interface Booking {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
}

export function BookingCalendar() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/bookings-api/bookings');
      if (!response.ok) {
        throw new Error(`Failed to fetch bookings: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (bookings.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No bookings available.</div>;
  }

  // Group bookings by date
  const groupedBookings: Record<string, Booking[]> = {};
  bookings.forEach(booking => {
    const date = booking.date;
    if (!groupedBookings[date]) {
      groupedBookings[date] = [];
    }
    groupedBookings[date].push(booking);
  });

  const dates = Object.keys(groupedBookings).sort();

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Darkroom Booking Calendar</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
        {dates.map(date => (
          <div key={date} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
            <h2 style={{ marginTop: '0', marginBottom: '10px' }}>{new Date(date).toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</h2>
