}

export function BookingCalendar() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [rangeOfficers, setRangeOfficers] = useState<RangeOfficer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchBookingsAndOfficers() {
      try {
        const [bookingsRes, officersRes] = await Promise.all([
          fetch('/api/bookings-api/bookings'),
          fetch('/api/bookings-api/range-officers')
        ]);

        if (!bookingsRes.ok || !officersRes.ok) {
          throw new Error('Failed to fetch data');
        }

        const bookingsData = await bookingsRes.json();
        const officersData = await officersRes.json();

        setBookings(bookingsData);
        setRangeOfficers(officersData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    }

    fetchBookingsAndOfficers();
  }, []);

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  const formatDate = (dateString: string) => {
    const options: Intl.DateTimeFormatOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  const formatTime = (timeString: string) => {
    const [hours, minutes] = timeString.split(':');
    const hour = parseInt(hours, 10);
    const ampm = hour >= 12 ? 'PM' : 'AM';
    const displayHour = hour % 12 || 12;
    return `${displayHour}:${minutes} ${ampm}`;
  };

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Booking Calendar</h1>

      {bookings.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No bookings available.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {bookings.map(booking => {
            const officer = rangeOfficers.find(o => o.id === booking.rangeOfficerId);
            return (
              <div key={booking.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                  <span><strong>Date:</strong> {formatDate(booking.date)}</span>
                  <span><strong>Time:</strong> {formatTime(booking.startTime)} - {formatTime(booking.endTime)}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span><strong>Range Officer:</strong> {officer?.name || 'Unknown'}</span>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Booking {
  id: number;
  date: string;
  time: string;
  laneNumber: number;
  memberId: number;
}

interface RangeOfficer {
  id: number;
