  try {
    const bookings = getAllBookings();
    res.json(bookings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch bookings" });
  }
});

router.get("/bookings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    res.json(booking);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch booking" });
  }
});

router.post("/bookings", (req: Request, res: Response) => {
  try {
    const { memberId, laneId, bookingTime } = req.body;

    if (!memberId || !laneId || !bookingTime) {
      return res.status(400).json({ error: "Member ID, lane ID, and booking time are required" });
    }

    const newId = insertBooking(memberId, laneId, bookingTime);
    const newBooking = getBookingById(newId);

    if (!newBooking) {
      return res.status(500).json({ error: "Failed to create booking" });
    }

    res.status(201).json(newBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to create booking" });
  }
});

