    if (!memberId || !laneId || !bookingTime) {
      return res.status(400).json({ error: "Member ID, lane ID, and booking time are required" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    updateBooking(id, memberId, laneId, bookingTime);
    const updatedBooking = getBookingById(id);

    if (!updatedBooking) {
      return res.status(500).json({ error: "Failed to update booking" });
