import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as reservationsRouter } from "../routes/reservations-api";
import { router as compRouter } from "../routes/comp-api";
import { router as emailConfirmationRouter } from "../routes/email-confirmation";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check comp-related requests
  if (!(req.path.startsWith("/comp") && req.method === "POST")) {
    next();
    return;
  }

  // Check if user is staff
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  const expectedSignature = createHmac("sha256", secret)
    .update(token)
    .digest();

  const providedSignature = Buffer.from(token, "base64");

  try {
    if (timingSafeEqual(expectedSignature, providedSignature)) {
      // Token is valid, allow access
      next();
    } else {
      res.status(401).json({ error: "Unauthorized" });
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
  }
}

import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  date: string;
  time: string;
  guestName: string;
  guestEmail: string;
}

export function ReservationCalendar() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [bookingForm, setBookingForm] = useState({
    guestName: '',
    guestEmail: '',
  });
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null);

  useEffect(() => {
    fetchReservations();
  }, [selectedDate]);

  const fetchReservations = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/reservations-api/?date=${selectedDate}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookSlot = async (slotId: string) => {
    if (!bookingForm.guestName || !bookingForm.guestEmail) {
      alert('Please fill in your name and email');
      return;
    }

    try {
      const response = await fetch(`/api/reservations-api/`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date: selectedDate,
          time: slotId,
          guestName: bookingForm.guestName,
          guestEmail: bookingForm.guestEmail,
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to book reservation: ${response.status} ${response.statusText}`);
      }

      // Reset form and refresh reservations
      setBookingForm({ guestName: '', guestEmail: '' });
      setSelectedSlot(null);
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBookingForm(prev => ({ ...prev, [name]: value }));
  };

  const getAvailableSlots = () => {
    const slots = [
      '09:00', '10:00', '11:00', '12:00',
      '13:00', '14:00', '15:00', '16:00'
    ];

    return slots.filter(slot => 
      !reservations.some(res => res.time === slot)
    );
  };

  const availableSlots = getAvailableSlots();

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Vineyard Tasting Room Reservations</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="datePicker" style={{ display: 'block', marginBottom: '5px' }}>
          Select Date:
        </label>
        <input
          type="date"
          id="datePicker"
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      <h2 style={{ textAlign: 'center' }}>Available Time Slots</h2>

      {availableSlots.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No available slots for this date.</p>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px', justifyContent: 'center' }}>
          {availableSlots.map(slot => (
            <button
              key={slot}
              onClick={() => handleBookSlot(slot)}
              style={{
                padding: '10px 15px',
                backgroundColor: '#4CAF50',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '16px',
                minWidth: '100px'
              }}
            >
              {slot}
            </button>
          ))}
        </div>
      )}

      <h2 style={{ textAlign: 'center', marginTop: '30px' }}>Book Your Slot</h2>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', maxWidth: '400px', margin: '0 auto' }}>
        <input
          type="text"
          name="guestName"
          placeholder="Your Name"
          value={bookingForm.guestName}
          onChange={handleInputChange}
          style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc', width: '100%' }}
        />
        <input
          type="email"
          name="guestEmail"
          placeholder="Your Email"
          value={bookingForm.guestEmail}
          onChange={handleInputChange}
          style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc', width: '100%' }}
        />
        <button
          onClick={() => {
            if (selectedSlot) {
              handleBookSlot(selectedSlot);
            }
          }}
          disabled={!selectedSlot}
          style={{
            padding: '10px',
            backgroundColor: selectedSlot ? '#2196F3' : '#ccc',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: selectedSlot ? 'pointer' : 'default',
            fontSize: '16px'
          }}
        >
          Book Selected Slot
        </button>
      </div>

      <h2 style={{ textAlign: 'center', marginTop: '30px' }}>Current Reservations</h2>

      {reservations.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No reservations found for this date.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '10px' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #ddd' }}>
              <th style={{ padding: '10px', textAlign: 'left' }}>Time</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Guest</th>
            </tr>
          </thead>
          <tbody>
            {reservations.map(res => (
              <tr key={res.id} style={{ borderBottom: '1px solid #eee' }}>
                <td style={{ padding: '10px' }}>{res.time}</td>
                <td style={{ padding: '10px' }}>{res.guestName}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  guestName: string;
  partySize: number;
  dateTime: string;
  status: "confirmed" | "completed" | "cancelled";
}

export function StaffCompPanel() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/reservations-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const markAsComp = async (id: string) => {
    try {
      const response = await fetch(`/api/comp-api/${id}/comp`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
      });

      if (!response.ok) {
        throw new Error(`Failed to mark reservation as comp: ${response.status}`);
      }

      // Refresh the list after marking as comp
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  if (reservations.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No reservations found.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Staff Comp Panel</h1>
      <p style={{ textAlign: "center", marginBottom: "30px" }}>Mark guest reservations as comps</p>

      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {reservations.map((reservation) => (
          <div 
            key={reservation.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              display: "flex", 
              justifyContent: "space-between", 
              alignItems: "center"
            }}
          >
            <div>
              <strong>{reservation.guestName}</strong>
              <br />
              Party of {reservation.partySize}
              <br />
              {new Date(reservation.dateTime).toLocaleString()}
              <br />
              Status: {reservation.status}
            </div>
            <button 
              onClick={() => markAsComp(reservation.id)}
              style={{ 
                backgroundColor: "#4CAF50", 
                color: "white", 
                border: "none", 
                borderRadius: "4px", 
                padding: "10px 15px", 
                cursor: "pointer"
              }}
            >
              Mark as Comp
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

