        throw new Error(`Failed to fetch plots: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setPlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleReserve = async (plotId: number) => {
    try {
      const response = await fetch(`/api/plots-api/${plotId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ available: false }),
      });

      if (!response.ok) {
        throw new Error(`Failed to reserve plot: ${response.status} ${response.statusText}`);
      }

      // Refresh the plot list after reservation
      await fetchPlots();
      setSelectedPlotId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
