          {plots.map(plot => (
            <div 
              key={plot.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                width: "200px", 
                backgroundColor: plot.available ? "#f0fff0" : "#fff0f0"
              }}
            >
              <h3>{plot.name}</h3>
              <p>Size: {plot.size}</p>
              <p>Status: {plot.available ? "Available" : "Reserved"}</p>
              {plot.available && (
                <button 
                  onClick={() => handleReserve(plot.id)}
                  style={{ 
                    backgroundColor: "#4CAF50", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    padding: "8px 12px", 
