import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/client-workout-tracker.db"
);

interface Workout {
  id: number;
  clientId: number;
  trainerId: number;
  exercise: string;
  date: string;
  notes: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS workouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    clientId INTEGER NOT NULL,
    trainerId INTEGER NOT NULL,
    exercise TEXT NOT NULL,
    date TEXT NOT NULL,
    notes TEXT
  );
`;

db.exec(createTableSql);

export function getAllWorkouts(): Workout[] {
  const stmt = db.prepare(`SELECT * FROM workouts`);
  return stmt.all() as unknown as Workout[];
}

export function getWorkoutById(id: number): Workout | undefined {
  const stmt = db.prepare(`SELECT * FROM workouts WHERE id = ?`);
  return stmt.get(id) as unknown as Workout | undefined;
}

export function insertWorkout(workout: Omit<Workout, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO workouts (clientId, trainerId, exercise, date, notes) VALUES (?, ?, ?, ?, ?)`
  );
  const result = stmt.run(
    workout.clientId,
    workout.trainerId,
    workout.exercise,
    workout.date,
    workout.notes
  );
  return Number(result.lastInsertRowid);
}

export function updateWorkout(
  id: number,
  workout: Partial<Omit<Workout, "id">>
): boolean {
  const fields = Object.keys(workout);
  if (fields.length === 0) return false;

  const setClause = fields.map(field => `${field} = ?`).join(", ");
  const sql = `UPDATE workouts SET ${setClause} WHERE id = ?`;
  const values = [...Object.values(workout), id];

  const stmt = db.prepare(sql);
  const result = stmt.run(...values);
  return result.changes > 0;
}

export function deleteWorkout(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM workouts WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

