import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Check if this is a deletion of a user record
  const pathSegments = req.path.split("/");
  const isUserDeletion = pathSegments.length >= 3 && pathSegments[1] === "users";

  if (!isUserDeletion) {
    next();
    return;
  }

  // Get the user ID from the URL path
  const userId = pathSegments[2];

  // Check if the user making the request is a supervisor
  const isSupervisor = req.headers["x-user-role"] === "supervisor";

  // If the requester is not a supervisor, allow the deletion
  if (!isSupervisor) {
    next();
    return;
  }

  // If the requester is a supervisor, check if they're trying to delete their own record
  const requestingUserId = req.headers["x-user-id"];

  if (requestingUserId === userId) {
    // Supervisor is deleting their own record - allow it
    next();
    return;
  }

  // Supervisor is trying to delete another user's record - reject it
  res.status(403).json({ message: "Supervisors can only delete their own records" });
}

