import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check deletion requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // For this middleware, we assume role checking is handled by a prior middleware
  // If there's no user object, we can't determine role, so we allow the request
  // In a real implementation, you'd want to ensure a prior auth middleware sets req.user
  const userRole = (req as any).user?.role;

  // If user has no role or is not supervisor, reject
  if (!userRole || userRole !== "supervisor") {
    res.status(403).json({ error: "Deletion access denied. Supervisor role required." });
    return;
  }

  // Allow supervisor to proceed
  next();
}

import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  startTime: string;
  endTime: string;
}

export function ReservationWidget() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newStartTime, setNewStartTime] = useState("");
  const [newEndTime, setNewEndTime] = useState("");

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/reservations-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateReservation = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/reservations-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          startTime: newStartTime,
          endTime: newEndTime,
        }),
      });
      if (!response.ok) {
        throw new Error(`Failed to create reservation: ${response.status}`);
      }
      setNewStartTime("");
      setNewEndTime("");
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteReservation = async (id: string) => {
    try {
      const response = await fetch(`/api/reservations-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete reservation: ${response.status}`);
      }
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center" }}>{error}</div>;

  return (
    <div style={{
      maxWidth: 600,
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    }}>
      <h1 style={{ textAlign: "center" }}>Parking Reservation</h1>

      <h2>Current Reservations</h2>
      {reservations.length === 0 ? (
        <p style={{ textAlign: "center" }}>No current reservations.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {reservations.map((reservation) => (
            <div 
              key={reservation.id} 
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "10px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <div>
                <strong>Start:</strong> {reservation.startTime}<br />
                <strong>End:</strong> {reservation.endTime}
              </div>
              <button 
                onClick={() => handleDeleteReservation(reservation.id)}
                style={{
                  backgroundColor: "#ff4d4d",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "5px 10px",
                  cursor: "pointer",
                }}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      )}

      <h2 style={{ marginTop: "30px" }}>Make New Reservation</h2>
      <form onSubmit={handleCreateReservation}>
        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="startTime">Start Time:</label><br />
          <input
            id="startTime"
            type="datetime-local"
            value={newStartTime}
            onChange={(e) => setNewStartTime(e.target.value)}
            style={{ width: "100%", padding: "8px" }}
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="endTime">End Time:</label><br />
          <input
            id="endTime"
            type="datetime-local"
            value={newEndTime}
            onChange={(e) => setNewEndTime(e.target.value)}
            style={{ width: "100%", padding: "8px" }}
          />
        </div>
        <button 
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            padding: "10px 20px",
            cursor: "pointer",
          }}
        >
          Reserve Slot
        </button>
      </form>
    </div>
  );
}

