  const isBookingRoute = req.path.startsWith("/bookings");
  const isAvailabilityRoute = req.path.startsWith("/availability");

  if (!isBookingRoute && !isAvailabilityRoute) {
    next();
    return;
  }

  // Check if user is supervisor
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd want proper JWT verification)
  try {
    // This is a simplified version - in practice, you'd decode and verify the JWT properly
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // In a real implementation, we would decode the payload to check role
    // For now, we'll assume the token contains a role claim
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    if (userRole !== "supervisor") {
      res.status(403).json({ error: "Forbidden: Supervisor access required" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

