import { Router, type Request, type Response } from "express";
import { getAllBookings, getBookingById } from "../db/bookings-table";
import { getAllRooms, getRoomById } from "../db/rooms-table";

export const router = Router();

// Get all rooms with their availability status
router.get("/available", (req: Request, res: Response) => {
  const rooms = getAllRooms();
  const bookings = getAllBookings();

  const roomsWithAvailability = rooms.map(room => {
    const roomBookings = bookings.filter(booking => booking.room_id === room.id);
    return {
      ...room,
      available: roomBookings.length < room.capacity
    };
  });

  res.json(roomsWithAvailability);
});

// Get a specific room with its availability status
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const room = getRoomById(id);

  if (!room) {
    return res.status(404).json({ error: "Room not found" });
  }

  const bookings = getAllBookings().filter(booking => booking.room_id === id);
  const available = bookings.length < room.capacity;

  res.json({
    ...room,
    available
  });
});

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./club-budget-tracker.db");

interface Expense {
  id: number;
  memberId: number;
  amount: number;
  description: string;
  approved: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS expenses (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    memberId INTEGER NOT NULL,
    amount REAL NOT NULL,
    description TEXT NOT NULL,
    approved BOOLEAN NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllExpenses(): Expense[] {
  const stmt = db.prepare("SELECT * FROM expenses");
  return stmt.all() as unknown as Expense[];
}

export function getExpenseById(id: number): Expense | undefined {
  const stmt = db.prepare("SELECT * FROM expenses WHERE id = ?");
  return stmt.get(id) as unknown as Expense | undefined;
}

export function insertExpense(
  memberId: number,
  amount: number,
  description: string,
  approved: boolean
): number {
  const stmt = db.prepare(
    "INSERT INTO expenses (memberId, amount, description, approved) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(memberId, amount, description, approved);
  return Number(result.lastInsertRowid);
}

export function updateExpense(
  id: number,
  memberId: number,
  amount: number,
  description: string,
  approved: boolean
): void {
  const stmt = db.prepare(
    "UPDATE expenses SET memberId = ?, amount = ?, description = ?, approved = ? WHERE id = ?"
  );
  stmt.run(memberId, amount, description, approved, id);
}

export function deleteExpense(id: number): void {
  const stmt = db.prepare("DELETE FROM expenses WHERE id = ?");
  stmt.run(id);
}

