import { Router, type Request, type Response } from "express";
import {
  db,
  deleteExpense,
  getAllExpenses,
  getExpenseById,
  insertExpense,
  updateExpense
} from "../db/expenses-table";

export const router = Router();

// Get all expenses
router.get("/", (req: Request, res: Response) => {
  try {
    const expenses = getAllExpenses();
    res.json(expenses);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch expenses" });
  }
});

// Get expense by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const expense = getExpenseById(id);
    if (!expense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    res.json(expense);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch expense" });
  }
});

// Create new expense
router.post("/", (req: Request, res: Response) => {
  try {
    const { memberId, amount, description, approved } = req.body;

    if (!memberId || !amount || !description || approved === undefined) {
      return res.status(400).json({
        error: "Member ID, amount, description, and approved status are required"
      });
    }

    const id = insertExpense(memberId, amount, description, approved);
    const newExpense = getExpenseById(id);

    if (!newExpense) {
      return res.status(500).json({ error: "Failed to create expense" });
    }

    res.status(201).json(newExpense);
  } catch (error) {
    res.status(500).json({ error: "Failed to create expense" });
  }
});

// Update expense
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { memberId, amount, description, approved } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    if (!memberId || !amount || !description || approved === undefined) {
      return res.status(400).json({
        error: "Member ID, amount, description, and approved status are required"
      });
    }

    const existingExpense = getExpenseById(id);
    if (!existingExpense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    updateExpense(id, memberId, amount, description, approved);
    const updatedExpense = getExpenseById(id);

    if (!updatedExpense) {
      return res.status(500).json({ error: "Failed to update expense" });
    }

    res.json(updatedExpense);
  } catch (error) {
    res.status(500).json({ error: "Failed to update expense" });
  }
});

// Delete expense (supervisor-only access)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const existingExpense = getExpenseById(id);
    if (!existingExpense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    deleteExpense(id);
    res.json({ message: "Expense deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete expense" });
  }
});

