export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests to the expenses API route
  if (req.method !== "DELETE" || !req.path.startsWith("/api/expenses")) {
    next();
    return;
  }

  // Check if user is supervisor
  // This is a placeholder implementation - in reality, this would
  // check the request context or session for supervisor status
  const isSupervisor = req.headers["x-user-role"] === "supervisor";

  if (!isSupervisor) {
