  if (isNaN(musicianId) || isNaN(rehearsalId)) {
    return res.status(400).json({ error: "Invalid musicianId or rehearsalId" });
  }

  if (!attendanceStatus) {
    return res.status(400).json({ error: "Missing required field: attendanceStatus" });
