  const updatedRows = updateRehearsal(musicianId, rehearsalId, attendanceStatus);

  if (updatedRows === 0) {
    return res.status(404).json({ error: "Rehearsal not found" });
  }

  res.json({ message: "Rehearsal updated successfully" });
