import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./data.db");

export interface Session {
  id: number;
  tutorId: number;
  sessionDate: string;
  topic: string;
  completed: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    tutorId INTEGER NOT NULL,
    sessionDate TEXT NOT NULL,
    topic TEXT NOT NULL,
    completed BOOLEAN DEFAULT FALSE
  );
`;

db.exec(createTableSql);

export function getAllSessions(): Session[] {
  const stmt = db.prepare(`SELECT * FROM sessions;`);
  return stmt.all() as unknown as Session[];
}

export function getSessionById(id: number): Session | undefined {
  const stmt = db.prepare(`SELECT * FROM sessions WHERE id = ?;`);
  return stmt.get(id) as unknown as Session | undefined;
}

export function insertSession(
  tutorId: number,
  sessionDate: string,
  topic: string,
  completed: boolean
): number {
  const stmt = db.prepare(
    `INSERT INTO sessions (tutorId, sessionDate, topic, completed) VALUES (?, ?, ?, ?);`
  );
  const result = stmt.run(tutorId, sessionDate, topic, completed);
  return Number(result.lastInsertRowid);
}

export function updateSession(
  id: number,
  tutorId: number,
  sessionDate: string,
  topic: string,
  completed: boolean
): void {
  const stmt = db.prepare(
    `UPDATE sessions SET tutorId = ?, sessionDate = ?, topic = ?, completed = ? WHERE id = ?;`
  );
  stmt.run(tutorId, sessionDate, topic, completed, id);
}

export function deleteSession(id: number): void {
  const stmt = db.prepare(`DELETE FROM sessions WHERE id = ?;`);
  stmt.run(id);
}

