export function SessionSearch() {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filter, setFilter] = useState<"tutor" | "date" | "topic">("tutor");

  useEffect(() => {
    fetchSessions();
  }, []);

  const fetchSessions = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/sessions-table/`);
      if (!response.ok) {
        throw new Error(`Failed to fetch sessions: ${response.status}`);
      }
      const data = await response.json();
      setSessions(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    fetchSessions();
  };

  const filteredSessions = sessions.filter(session => {
    if (!searchTerm) return true;
    switch (filter) {
      case "tutor":
        return session.tutor.toLowerCase().includes(searchTerm.toLowerCase());
      case "date":
        return session.date.toLowerCase().includes(searchTerm.toLowerCase());
      case "topic":
        return session.topic.toLowerCase().includes(searchTerm.toLowerCase());
      default:
        return true;
    }
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Session Search</h1>

      <form onSubmit={handleSearch} style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc", width: "100%" }}
        />
        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value as "tutor" | "date" | "topic")}
          style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc", width: "100%" }}
        >
          <option value="tutor">Search by Tutor</option>
          <option value="date">Search by Date</option>
          <option value="topic">Search by Topic</option>
        </select>
        <button type="submit" style={{ padding: "10px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}>
          Search
        </button>
      </form>

      {filteredSessions.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No sessions found.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {filteredSessions.map((session) => (
            <div key={session.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", width: "100%", maxWidth: "300px" }}>
              <h3>{session.tutor}</h3>
              <p><strong>Date:</strong> {session.date}</p>
              <p><strong>Topic:</strong> {session.topic}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./data.db");

export interface Session {
  id: number;
  tutorId: number;
  sessionDate: string;
  topic: string;
  completed: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    tutorId INTEGER NOT NULL,
    sessionDate TEXT NOT NULL,
    topic TEXT NOT NULL,
    completed BOOLEAN DEFAULT FALSE
  );
`;

db.exec(createTableSql);

export function getAllSessions(): Session[] {
  const stmt = db.prepare(`SELECT * FROM sessions;`);
  return stmt.all() as unknown as Session[];
}

export function getSessionById(id: number): Session | undefined {
  const stmt = db.prepare(`SELECT * FROM sessions WHERE id = ?;`);
  return stmt.get(id) as unknown as Session | undefined;
}

export function insertSession(
  tutorId: number,
  sessionDate: string,
  topic: string,
  completed: boolean
): number {
  const stmt = db.prepare(
    `INSERT INTO sessions (tutorId, sessionDate, topic, completed) VALUES (?, ?, ?, ?);`
  );
  const result = stmt.run(tutorId, sessionDate, topic, completed);
  return Number(result.lastInsertRowid);
}

export function updateSession(
  id: number,
  tutorId: number,
  sessionDate: string,
  topic: string,
  completed: boolean
): void {
  const stmt = db.prepare(
    `UPDATE sessions SET tutorId = ?, sessionDate = ?, topic = ?, completed = ? WHERE id = ?;`
  );
  stmt.run(tutorId, sessionDate, topic, completed, id);
}

export function deleteSession(id: number): void {
  const stmt = db.prepare(`DELETE FROM sessions WHERE id = ?;`);
  stmt.run(id);
}

