import { Router, type Request, type Response } from "express";

const router = Router();

// Mock submission data storage
let submissions = [
  { id: 1, title: "Introduction to TypeScript", author: "John Doe", status: "submitted" },
  { id: 2, title: "Advanced React Patterns", author: "Jane Smith", status: "reviewed" }
];

// Get all submissions
router.get("/", (req: Request, res: Response) => {
  res.json(submissions);
});

// Get a submission by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const submission = submissions.find(s => s.id === id);

  if (!submission) {
    return res.status(404).json({ error: "Submission not found" });
  }

  res.json(submission);
});

// Create a new submission
router.post("/", (req: Request, res: Response) => {
  const { title, author } = req.body;

  if (!title || !author) {
    return res.status(400).json({ error: "Title and author are required" });
  }

  const newId = submissions.length > 0 ? Math.max(...submissions.map(s => s.id)) + 1 : 1;
  const newSubmission = {
    id: newId,
    title,
    author,
    status: "submitted"
  };

  submissions.push(newSubmission);
  res.status(201).json(newSubmission);
});

// Update a submission
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { title, author, status } = req.body;

  const submissionIndex = submissions.findIndex(s => s.id === id);

  if (submissionIndex === -1) {
    return res.status(404).json({ error: "Submission not found" });
  }

  submissions[submissionIndex] = {
    ...submissions[submissionIndex],
    ...(title && { title }),
    ...(author && { author }),
    ...(status && { status })
  };

  res.json(submissions[submissionIndex]);
});

// Delete a submission
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const submissionIndex = submissions.findIndex(s => s.id === id);

  if (submissionIndex === -1) {
    return res.status(404).json({ error: "Submission not found" });
  }

  submissions.splice(submissionIndex, 1);
  res.json({ message: "Submission deleted successfully" });
});

