import type { Request, Response, NextFunction } from "express";
import { router as submissionsRouter } from "../routes/submissions-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check deletion requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Check if the request is for the submissions API
  const submissionsPath = "/submissions";
  if (!req.path.startsWith(submissionsPath)) {
    next();
    return;
  }

  // For now, we'll just pass through all DELETE requests to submissions
  // In a real implementation, this would check user permissions
  next();
}

