import { Router, type Request, type Response } from "express";
import {
  deleteBooking,
  getAllBookings,
  getBookingById,
  insertBooking,
  updateBooking
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  try {
    const bookings = getAllBookings();
    return res.json(bookings);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch bookings" });
  }
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    return res.json(booking);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch booking" });
  }
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  try {
    const { memberId, slotTime, isSupervisor } = req.body;

    if (!memberId || !slotTime) {
      return res.status(400).json({ error: "Member ID and slot time are required" });
    }

    const id = insertBooking(memberId, slotTime, isSupervisor || false);
    const newBooking = getBookingById(id);

    if (!newBooking) {
      return res.status(500).json({ error: "Failed to create booking" });
    }

    return res.status(201).json(newBooking);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create booking" });
  }
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { memberId, slotTime, isSupervisor } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    if (!memberId || !slotTime) {
      return res.status(400).json({ error: "Member ID and slot time are required" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    updateBooking(id, memberId, slotTime, isSupervisor || false);
    const updatedBooking = getBookingById(id);

    if (!updatedBooking) {
      return res.status(500).json({ error: "Failed to update booking" });
    }

    return res.json(updatedBooking);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update booking" });
  }
});

// Delete a booking (supervisor-only)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const isSupervisor = req.body.isSupervisor === true;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    if (!isSupervisor) {
      return res.status(403).json({ error: "Only supervisors can delete bookings" });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    deleteBooking(id);
    return res.json({ message: "Booking deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete booking" });
  }
});

import type { Request, Response, NextFunction } from "express";
