export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check deletion requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Check if the request is for the bookings API
  if (!req.path.startsWith("/bookings")) {
    next();
    return;
  }

  // For now, we'll just pass through -
  // In a real implementation, this would check user permissions
  // and reject non-supervisors from deleting bookings
  next();
}

import { useEffect, useState } from "react";

interface BookingSlot {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
  booked: boolean;
}

export function BookingCalendar() {
  const [slots, setSlots] = useState<BookingSlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch bookings: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setSlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookSlot = async (id: string) => {
    try {
      const response = await fetch(`/api/bookings-api/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ booked: true }),
      });

      if (!response.ok) {
        throw new Error(`Failed to book slot: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after booking
      await fetchBookings();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (slots.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No available slots.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Darkroom Booking</h1>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
        {slots.map((slot) => (
          <div 
            key={slot.id} 
            style={{ 
              border: '1px solid #ccc', 
              borderRadius: '8px', 
              padding: '15px', 
              width: '100%', 
              maxWidth: '300px'
            }}
          >
            <p><strong>Date:</strong> {slot.date}</p>
            <p><strong>Time:</strong> {slot.startTime} - {slot.endTime}</p>
            <button 
              onClick={() => handleBookSlot(slot.id)}
              disabled={slot.booked}
              style={{ 
                backgroundColor: slot.booked ? '#ccc' : '#007bff', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px', 
                padding: '8px 12px', 
                cursor: slot.booked ? 'default' : 'pointer',
                marginTop: '10px'
              }}
            >
              {slot.booked ? 'Booked' : 'Book Now'}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

