import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as schedulingRouter } from "../routes/scheduling-api";
import { router as supervisorRoleCheckRouter } from "../routes/supervisor-role-check";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests to the scheduling API routes
  if (req.method !== "DELETE" || !req.path.startsWith("/api/scheduling")) {
    next();
    return;
  }

  // Check if the user is a supervisor
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd want proper JWT verification)
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  // Create expected signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const isValid = timingSafeEqual(
    Buffer.from(signature, "base64url"),
    Buffer.from(expectedSignature, "base64url")
  );

  if (!isValid) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // For demonstration purposes, we'll assume the payload contains user info
  // In a real implementation, you'd decode the JWT properly
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userId = decodedPayload.userId;
    const supervisorId = req.params.id; // Assuming the ID is in params

    if (userId === supervisorId) {
      res.status(403).json({ error: "Supervisors cannot delete their own records" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }
}

import { useEffect, useState } from "react";

interface Slot {
  id: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

export function AirtimeSlotClaimUi() {
  const [slots, setSlots] = useState<Slot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSlots();
  }, []);

  const fetchSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/scheduling-api/slots');
      if (!response.ok) {
        throw new Error(`Failed to fetch slots: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setSlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleClaimSlot = async (slotId: string) => {
    try {
      const response = await fetch(`/api/scheduling-api/slots/${slotId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ claimedBy: 'current-dj' }),
      });

      if (!response.ok) {
        throw new Error(`Failed to claim slot: ${response.status} ${response.statusText}`);
      }

      // Refresh the slot list after claiming
      await fetchSlots();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleReleaseSlot = async (slotId: string) => {
    try {
      const response = await fetch(`/api/scheduling-api/slots/${slotId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ claimedBy: null }),
      });

      if (!response.ok) {
        throw new Error(`Failed to release slot: ${response.status} ${response.statusText}`);
      }

      // Refresh the slot list after releasing
      await fetchSlots();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif',
    }}>
      <h1>Airtime Slot Claim</h1>
      {slots.length === 0 ? (
        <p style={{ textAlign: 'center' }}>No available slots.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {slots.map((slot) => (
            <div 
              key={slot.id} 
              style={{
                border: '1px solid #ccc',
                borderRadius: '8px',
                padding: '15px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
              }}
            >
              <div>
                <strong>{new Date(slot.startTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</strong>
                {' - '}
                <span>{new Date(slot.endTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                {slot.claimedBy && (
                  <span style={{ marginLeft: '10px', color: '#666' }}>
                    (Claimed by {slot.claimedBy})
                  </span>
                )}
              </div>
              <div>
                {slot.claimedBy ? (
                  <button 
                    onClick={() => handleReleaseSlot(slot.id)}
                    style={{
                      backgroundColor: '#f44336',
                      color: 'white',
                      border: 'none',
                      padding: '8px 12px',
                      borderRadius: '4px',
                      cursor: 'pointer',
                    }}
                  >
                    Release
                  </button>
                ) : (
                  <button 
                    onClick={() => handleClaimSlot(slot.id)}
                    style={{
                      backgroundColor: '#4CAF50',
                      color: 'white',
                      border: 'none',
                      padding: '8px 12px',
                      borderRadius: '4px',
                      cursor: 'pointer',
                    }}
                  >
                    Claim
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

