import { useEffect, useState } from "react";

export function SupervisorModeToggle() {
  const [isSupervisor, setIsSupervisor] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkSupervisorRole = async () => {
      try {
        const response = await fetch('/api/supervisor-role-check/airtime-slots/1');
        if (response.ok) {
          setIsSupervisor(true);
        } else {
          setIsSupervisor(false);
        }
      } catch (err) {
        setError('Failed to check supervisor role');
      } finally {
        setLoading(false);
      }
    };

    checkSupervisorRole();
  }, []);

  const toggleSupervisorMode = async () => {
    setLoading(true);
    setError(null);

    try {
      if (isSupervisor) {
        // Exit supervisor mode
        const response = await fetch('/api/supervisor-role-check/airtime-slots/1', {
          method: 'DELETE'
        });
        if (response.ok) {
          setIsSupervisor(false);
        } else {
          setError('Failed to exit supervisor mode');
        }
      } else {
        // Enter supervisor mode
        const response = await fetch('/api/supervisor-role-check/airtime-slots/1', {
          method: 'POST'
        });
        if (response.ok) {
          setIsSupervisor(true);
        } else {
          setError('Failed to enter supervisor mode');
        }
      }
    } catch (err) {
      setError('Network error occurred');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  return (
    <div style={{
      maxWidth: '600px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1>Supervisor Mode</h1>
      <p>Current status: {isSupervisor ? 'Active' : 'Inactive'}</p>
      <button 
        onClick={toggleSupervisorMode}
        style={{
          backgroundColor: isSupervisor ? '#ff4444' : '#4444ff',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          padding: '10px 20px',
          fontSize: '16px',
          cursor: 'pointer'
        }}
      >
        {isSupervisor ? 'Exit Supervisor Mode' : 'Enter Supervisor Mode'}
      </button>
      {error && <p style={{ color: 'red', marginTop: '10px' }}>{error}</p>}
    </div>
  );
}

