const isSupervisor = (req: Request, res: Response, next: Function) => {
  // Assuming supervisor status is stored in req.user.role
  const userRole = req.headers.role as string;

  if (userRole !== "supervisor") {
    return res.status(403).json({ error: "Access denied. Supervisor role required." });
  }

  next();
};

// DELETE route for booking - protected by supervisor guard
