});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check deletion requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Check if this is a deletion request to a kitchen resource
  if (!req.path.startsWith("/kitchens/")) {
    next();
    return;
  }

  // Get the user role from the request headers
  const userRole = req.headers["x-user-role"];

  // If no role is provided, reject the request
  if (!userRole || Array.isArray(userRole)) {
    res.status(403).json({ error: "Access denied: supervisor required" });
    return;
  }

  // Check if the user is a supervisor
  if (userRole !== "supervisor") {
    res.status(403).json({ error: "Access denied: supervisor required" });
    return;
  }

  // If user is supervisor, allow the request to proceed
  next();
}

import { useEffect, useState } from "react";

interface TimeSlot {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
  available: boolean;
}

export function BookingCalendar() {
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTimeSlots();
  }, []);

  const fetchTimeSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/rental-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setTimeSlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleBookSlot = async (id: string) => {
    try {
      const response = await fetch(`/api/rental-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ available: false }),
      });

      if (!response.ok) {
        throw new Error(`Failed to book slot: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after booking
      await fetchTimeSlots();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (timeSlots.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No available time slots.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Kitchen Booking Calendar</h1>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
        {timeSlots.map((slot) => (
          <div 
            key={slot.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              width: "100%", 
              maxWidth: "300px", 
              boxSizing: "border-box"
            }}
          >
            <p><strong>Date:</strong> {slot.date}</p>
            <p><strong>Time:</strong> {slot.startTime} - {slot.endTime}</p>
            <button 
              onClick={() => handleBookSlot(slot.id)}
              disabled={!slot.available}
              style={{ 
                backgroundColor: slot.available ? "#007bff" : "#ccc", 
                color: "white", 
                border: "none", 
                borderRadius: "4px", 
                padding: "8px 12px", 
                cursor: slot.available ? "pointer" : "default",
                marginTop: "10px"
              }}
            >
              {slot.available ? "Book Slot" : "Booked"}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

