import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./volunteer-shift-signup.db"
);

interface ShiftRow {
  volunteer_id: number;
  shift_id: number;
  signup_timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shifts (
    volunteer_id INTEGER NOT NULL,
    shift_id INTEGER NOT NULL,
    signup_timestamp TEXT NOT NULL,
    PRIMARY KEY (volunteer_id, shift_id)
  )
`;

db.exec(createTableSql);

export function getAllShifts(): ShiftRow[] {
  const stmt = db.prepare(`SELECT * FROM shifts`);
  return stmt.all() as unknown as ShiftRow[];
}

export function getShiftById(
  volunteerId: number,
  shiftId: number
): ShiftRow | undefined {
  const stmt = db.prepare(
    `SELECT * FROM shifts WHERE volunteer_id = ? AND shift_id = ?`
  );
  return stmt.get(volunteerId, shiftId) as unknown as ShiftRow | undefined;
}

export function insertShift(
  volunteerId: number,
  shiftId: number,
  signupTimestamp: string
): number {
  const stmt = db.prepare(
    `INSERT INTO shifts (volunteer_id, shift_id, signup_timestamp)
     VALUES (?, ?, ?)`
  );
  const result = stmt.run(volunteerId, shiftId, signupTimestamp);
  return Number(result.lastInsertRowid);
}

export function updateShift(
  volunteerId: number,
  shiftId: number,
  signupTimestamp: string
): number {
  const stmt = db.prepare(
    `UPDATE shifts
     SET signup_timestamp = ?
     WHERE volunteer_id = ? AND shift_id = ?`
  );
  const result = stmt.run(signupTimestamp, volunteerId, shiftId);
  return Number(result.changes);
}

export function deleteShift(
  volunteerId: number,
  shiftId: number
): number {
  const stmt = db.prepare(
    `DELETE FROM shifts WHERE volunteer_id = ? AND shift_id = ?`
  );
  const result = stmt.run(volunteerId, shiftId);
  return Number(result.changes);
}

