export function OwnerOnlyExportButton({ volunteerId }: OwnerOnlyExportButtonProps) {
  const [isOwner, setIsOwner] = useState<boolean | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const checkOwner = async () => {
      try {
        const response = await fetch(`/api/owner-check-middleware`, {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
          },
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        setIsOwner(data.isOwner);
      } catch (error) {
        console.error("Failed to check owner status:", error);
        setIsOwner(false);
      } finally {
        setLoading(false);
      }
    };

    checkOwner();
  }, []);

  const handleExport = async () => {
    try {
      const response = await fetch(`/api/shifts-table/`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      // Create CSV content
      let csvContent = "Volunteer ID,Shift ID,Status\n";
      data.forEach((row: any) => {
        csvContent += `${row.volunteerId},${row.shiftId},${row.status}\n`;
      });

      // Create download link
      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.setAttribute("href", url);
      link.setAttribute("download", "shifts-export.csv");
      link.style.visibility = "hidden";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error("Failed to export shifts:", error);
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center" }}>Loading...</div>;
  }

  if (isOwner === false) {
    return null;
  }

  return (
    <button
      onClick={handleExport}
