  timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shifts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    claimed_member_id INTEGER,
    timestamp TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllShifts(): Shift[] {
  const stmt = db.prepare("SELECT * FROM shifts");
  return stmt.all() as unknown as Shift[];
}

export function getShiftById(id: number): Shift | undefined {
  const stmt = db.prepare("SELECT * FROM shifts WHERE id = ?");
  return stmt.get(id) as unknown as Shift | undefined;
}

export function insertShift(claimedMemberId: number | null, timestamp: string): number {
  const stmt = db.prepare(
    "INSERT INTO shifts (claimed_member_id, timestamp) VALUES (?, ?)"
  );
  const result = stmt.run(claimedMemberId, timestamp);
  return Number(result.lastInsertRowid);
}

export function updateShift(id: number, claimedMemberId: number | null, timestamp: string): void {
  const stmt = db.prepare(
    "UPDATE shifts SET claimed_member_id = ?, timestamp = ? WHERE id = ?"
  );
  stmt.run(claimedMemberId, timestamp, id);
}

export function deleteShift(id: number): void {
  const stmt = db.prepare("DELETE FROM shifts WHERE id = ?");
  stmt.run(id);
}

