import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as shiftsApiRouter } from "../routes/shifts-api";
import { router as exportServiceRouter } from "../routes/export-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check export-related requests
  if (!(req.path.startsWith("/api/export") && req.method === "GET")) {
    next();
    return;
  }

  // Check if user is owner
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (assuming token format is owner:signature)
  const parts = token.split(":");
  if (parts.length !== 2) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [owner, signature] = parts;
  const expectedSignature = createHmac("sha256", secret)
    .update(owner)
    .digest("hex");

  try {
    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    if (actualBuffer.length !== expectedBuffer.length ||
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // For demo purposes, we'll just check if owner is "admin"
  // In a real implementation, this would be a proper ownership check
  if (owner !== "admin") {
    res.status(403).json({ error: "Forbidden: Only board owner can export" });
    return;
  }

  next();
}

