import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./food-bank.db");

interface Donation {
  id: number;
  itemName: string;
  quantity: number;
  volunteerId: number;
  date: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS donations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    itemName TEXT NOT NULL,
    quantity INTEGER NOT NULL,
    volunteerId INTEGER NOT NULL,
    date TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllDonations(): Donation[] {
  const stmt = db.prepare("SELECT * FROM donations");
  return stmt.all() as unknown as Donation[];
}

export function getDonationById(id: number): Donation | undefined {
  const stmt = db.prepare("SELECT * FROM donations WHERE id = ?");
  return stmt.get(id) as unknown as Donation | undefined;
}

export function insertDonation(
  itemName: string,
  quantity: number,
  volunteerId: number,
  date: string
): number {
  const stmt = db.prepare(
    "INSERT INTO donations (itemName, quantity, volunteerId, date) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(itemName, quantity, volunteerId, date);
  return Number(result.lastInsertRowid);
}

export function updateDonation(
  id: number,
  itemName: string,
  quantity: number,
  volunteerId: number,
  date: string
): number {
  const stmt = db.prepare(
    "UPDATE donations SET itemName = ?, quantity = ?, volunteerId = ?, date = ? WHERE id = ?"
  );
  const result = stmt.run(itemName, quantity, volunteerId, date, id);
  return Number(result.changes);
}

export function deleteDonation(id: number): number {
  const stmt = db.prepare("DELETE FROM donations WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

