import { Router, type Request, type Response } from "express";
import { getAllOrders } from "../db/orders-table";

export const router = Router();

router.get("/export", (req: Request, res: Response) => {
  // Check for owner token
  const ownerToken = req.headers["x-owner-token"];
  if (!ownerToken || ownerToken !== "secret-owner-token") {
    return res.status(401).json({ error: "Unauthorized" });
  }

  // Get all orders
  const orders = getAllOrders();

  // Generate CSV content
  let csvContent = "id,customerId,flavour,size,date\n";
  for (const order of orders) {
    csvContent += `${order.id},${order.customerId},${order.flavour},${order.size},${order.date}\n`;
  }

  // Set response headers
  res.setHeader("Content-Type", "text/csv");
  res.setHeader("Content-Disposition", "attachment; filename=orders.csv");

  // Send CSV content
  res.send(csvContent);
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || !req.path.startsWith("/export")) {
    next();
    return;
  }

  // Check if the user is an owner
  const userRole = req.headers["x-user-role"];

  if (userRole === "owner") {
    next();
  } else {
    res.status(403).json({ error: "Access denied. Owner privileges required." });
  }
}

