import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./community-pool.db");

interface Shift {
  id: number;
  lifeguardId: number;
  shiftTime: string;
  poolId: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shifts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    lifeguardId INTEGER NOT NULL,
    shiftTime TEXT NOT NULL,
    poolId INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllShifts(): Shift[] {
  const stmt = db.prepare("SELECT * FROM shifts");
  return stmt.all() as unknown as Shift[];
}

export function getShiftById(id: number): Shift | undefined {
  const stmt = db.prepare("SELECT * FROM shifts WHERE id = ?");
  return stmt.get(id) as unknown as Shift | undefined;
}

export function insertShift(shift: Omit<Shift, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO shifts (lifeguardId, shiftTime, poolId) VALUES (?, ?, ?)"
  );
  const result = stmt.run(shift.lifeguardId, shift.shiftTime, shift.poolId);
  return Number(result.lastInsertRowid);
}

export function updateShift(id: number, shift: Partial<Shift>): boolean {
  const fields = [];
  const values: (number | string)[] = [];

  if (shift.lifeguardId !== undefined) {
    fields.push("lifeguardId = ?");
    values.push(shift.lifeguardId);
  }

  if (shift.shiftTime !== undefined) {
    fields.push("shiftTime = ?");
    values.push(shift.shiftTime);
  }

  if (shift.poolId !== undefined) {
    fields.push("poolId = ?");
    values.push(shift.poolId);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE shifts SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteShift(id: number): boolean {
  const stmt = db.prepare("DELETE FROM shifts WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

