  accountId: number;
  isOwner: boolean;
}

// GET /shifts - Get all shifts
router.get("/shifts", (req: Request, res: Response) => {
  try {
    const shifts = getAllShifts();
    return res.json(shifts);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch shifts" });
  }
});

// GET /shifts/:id - Get a specific shift by ID
router.get("/shifts/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift ID" });
    }

    const shift = getShiftById(id);
    if (!shift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    return res.json(shift);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch shift" });
  }
});

// POST /shifts - Create a new shift
router.post("/shifts", (req: Request, res: Response) => {
  try {
    const { accountId, date, startTime, endTime, poolId } = req.body;

    // Validate required fields
    if (!accountId || !date || !startTime || !endTime || !poolId) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    // Check if the user is an owner
    const owner = getOwner(accountId);
    if (!owner || !owner.isOwner) {
      return res.status(403).json({ error: "Only owners can create shifts" });
    }

    const newShift = {
      accountId,
      date,
      startTime,
      endTime,
      poolId
    };

    const shiftId = insertShift(newShift);

    return res.status(201).json({
      id: shiftId,
      ...newShift
    });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create shift" });
  }
});

