  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift ID" });
    }

    const { accountId, date, startTime, endTime, poolId } = req.body;

    // Check if the shift exists
    const existingShift = getShiftById(id);
    if (!existingShift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    // Check if the user is an owner
    const owner = getOwner(accountId);
    if (!owner || !owner.isOwner) {
      return res.status(403).json({ error: "Only owners can update shifts" });
    }

    const updatedFields: Partial<Shift> = {};
    if (date !== undefined) updatedFields.date = date;
    if (startTime !== undefined) updatedFields.startTime = startTime;
    if (endTime !== undefined) updatedFields.endTime = endTime;
    if (poolId !== undefined) updatedFields.poolId = poolId;

    const success = updateShift(id, updatedFields);

    if (!success) {
      return res.status(500).json({ error: "Failed to update shift" });
    }

    return res.json({ message: "Shift updated successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to update shift" });
  }
});

