import { router as shiftsApiRouter } from "../routes/shifts-api";
import { router as exportServiceRouter } from "../routes/export-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check export-related requests
  const isExportRequest = 
    req.path.startsWith("/api/shifts/export") ||
    req.path.startsWith("/api/export");

  if (!isExportRequest) {
    next();
    return;
  }

  // Check if the request is from the owner
  // For this example, we'll assume there's an owner ID stored in the session
  // In a real implementation, this would involve checking authentication tokens
  // and comparing the user ID against the owner ID

  // Since we're simulating owner-only access, we'll just check a mock condition
  // In practice, this should verify JWT or session ownership

  // Mock owner check - in reality this would be proper authentication
  const isOwner = req.headers["x-owner"] === "true";

  if (!isOwner) {
    res.status(403).json({ error: "Export access denied. Owner only." });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

interface Shift {
  id: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

export function ShiftClaimBoard() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/shifts-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch shifts: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleClaim = async (shiftId: string) => {
    try {
      const response = await fetch(`/api/shifts-api/${shiftId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ claimedBy: "current-user" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to claim shift: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleUnclaim = async (shiftId: string) => {
    try {
      const response = await fetch(`/api/shifts-api/${shiftId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ claimedBy: null }),
      });

      if (!response.ok) {
        throw new Error(`Failed to unclaim shift: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (shifts.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No open shifts available for today.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Open Shifts</h1>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
        {shifts.map((shift) => (
          <div 
            key={shift.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              width: "100%", 
              maxWidth: "300px"
            }}
          >
            <div style={{ marginBottom: "10px" }}>
              <strong>Start:</strong> {new Date(shift.startTime).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>End:</strong> {new Date(shift.endTime).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
            </div>
            <div style={{ marginBottom: "10px" }}>
              {shift.claimedBy ? (
                <span>Claimed by: {shift.claimedBy}</span>
              ) : (
                <span>Open for claiming</span>
              )}
            </div>
            <div>
              {shift.claimedBy ? (
                <button 
                  onClick={() => handleUnclaim(shift.id)}
                  style={{ 
                    backgroundColor: "#f44336", 
                    color: "white", 
                    border: "none", 
                    padding: "8px 12px", 
                    borderRadius: "4px", 
                    cursor: "pointer"
                  }}
                >
                  Unclaim
                </button>
              ) : (
                <button 
                  onClick={() => handleClaim(shift.id)}
                  style={{ 
                    backgroundColor: "#4CAF50", 
                    color: "white", 
                    border: "none", 
                    padding: "8px 12px", 
                    borderRadius: "4px", 
                    cursor: "pointer"
                  }}
                >
                  Claim
                </button>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

import { FC, useState } from "react";

export function ExportHistoryButton() {
  const [isExporting, setIsExporting] = useState(false);
  const [exportError, setExportError] = useState<string | null>(null);

  const handleExport = async () => {
    setIsExporting(true);
    setExportError(null);

    try {
      const response = await fetch('/api/export-service/export', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/csv',
        },
      });

      if (!response.ok) {
        throw new Error(`Export failed: ${response.status} ${response.statusText}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'shift_history.csv';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error) {
      setExportError(error instanceof Error ? error.message : 'An unknown error occurred');
    } finally {
      setIsExporting(false);
    }
  };

  // This component should only be visible to the owner account
  // In a real app, you'd check auth status here
  const userIsOwner = true; // Placeholder - in reality this would come from auth context

  if (!userIsOwner) {
    return null;
  }

  return (
    <div style={{
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      padding: '20px',
      maxWidth: '600px',
      margin: '0 auto',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    }}>
      <button
        onClick={handleExport}
        disabled={isExporting}
        style={{
          backgroundColor: '#007bff',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          padding: '10px 20px',
          fontSize: '16px',
          cursor: isExporting ? 'not-allowed' : 'pointer',
          transition: 'background-color 0.2s',
        }}
      >
        {isExporting ? 'Exporting...' : 'Export Shift History'}
      </button>

      {exportError && (
        <div style={{
          marginTop: '10px',
          color: 'red',
          textAlign: 'center',
        }}>
          {exportError}
        </div>
      )}
    </div>
  );
}

