interface MachineRow {
  id: number;
  status: string;
  report_timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS machines (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    status TEXT NOT NULL,
    report_timestamp TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllMachines(): MachineRow[] {
  const stmt = db.prepare(`SELECT * FROM machines`);
  return stmt.all() as unknown as MachineRow[];
}

export function getMachineById(id: number): MachineRow | undefined {
  const stmt = db.prepare(
    `SELECT * FROM machines WHERE id = ?`
  );
  return stmt.get(id) as unknown as MachineRow | undefined;
}

export function insertMachine(
  status: string,
  reportTimestamp: string
): number {
  const stmt = db.prepare(
    `INSERT INTO machines (status, report_timestamp) VALUES (?, ?)`
  );
  const result = stmt.run(status, reportTimestamp);
  return Number(result.lastInsertRowid);
}

export function updateMachine(
  id: number,
  status: string,
  reportTimestamp: string
): void {
  const stmt = db.prepare(
    `UPDATE machines SET status = ?, report_timestamp = ? WHERE id = ?`
  );
  stmt.run(status, reportTimestamp, id);
}

export function deleteMachine(id: number): void {
  const stmt = db.prepare(`DELETE FROM machines WHERE id = ?`);
  stmt.run(id);
}

