import { Router, type Request, type Response } from "express";
import { db, deleteMachine, getAllMachines, getMachineById, insertMachine, updateMachine } from "../db/machines-table";

export const router = Router();

// GET /machines - Get all machines
router.get("/machines", (req: Request, res: Response) => {
  const machines = getAllMachines();
  res.json(machines);
});

// GET /machines/:id - Get a specific machine by ID
router.get("/machines/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const machine = getMachineById(id);

  if (!machine) {
    return res.status(404).json({ error: "Machine not found" });
  }

  res.json(machine);
});

// POST /machines - Create a new machine
router.post("/machines", (req: Request, res: Response) => {
  const { status, reportTimestamp } = req.body;

  if (!status || !reportTimestamp) {
    return res.status(400).json({ error: "Status and report timestamp are required" });
  }

  const id = insertMachine(status, reportTimestamp);
  const newMachine = getMachineById(id);

  if (!newMachine) {
    return res.status(500).json({ error: "Failed to create machine" });
  }

  res.status(201).json(newMachine);
});

// PUT /machines/:id - Update an existing machine
router.put("/machines/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { status, reportTimestamp } = req.body;

  if (!status || !reportTimestamp) {
    return res.status(400).json({ error: "Status and report timestamp are required" });
  }

  const existingMachine = getMachineById(id);

  if (!existingMachine) {
    return res.status(404).json({ error: "Machine not found" });
  }

  updateMachine(id, status, reportTimestamp);
  const updatedMachine = getMachineById(id);

  if (!updatedMachine) {
    return res.status(500).json({ error: "Failed to update machine" });
  }

  res.json(updatedMachine);
});

// DELETE /machines/:id - Delete a machine
router.delete("/machines/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  const existingMachine = getMachineById(id);

  if (!existingMachine) {
    return res.status(404).json({ error: "Machine not found" });
  }

  deleteMachine(id);

  res.json({ message: "Machine deleted successfully" });
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  // Check if the request has an owner role in the session or headers
  // This is a simplified check - in a real implementation, you'd verify a JWT token
  const ownerRole = req.headers["x-owner-role"];

