export function MachineReportForm() {
  const [machines, setMachines] = useState<Machine[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedMachineId, setSelectedMachineId] = useState<number | null>(null);
  const [reporting, setReporting] = useState(false);

  useEffect(() => {
    fetchMachines();
  }, []);

  const fetchMachines = async () => {
    try {
      const response = await fetch("/api/machines-api/machines");
      if (!response.ok) {
        throw new Error(`Failed to fetch machines: ${response.status}`);
      }
      const data = await response.json();
      setMachines(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleReportBroken = async () => {
    if (selectedMachineId === null) return;

    setReporting(true);
    try {
      const response = await fetch(`/api/machines-api/machines/${selectedMachineId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "broken" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update machine: ${response.status}`);
      }

      // Refresh the machine list
      await fetchMachines();
      setSelectedMachineId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setReporting(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
