      <h1 style={{ textAlign: "center" }}>Report Broken Machine</h1>

      {machines.length === 0 ? (
        <p style={{ textAlign: "center" }}>No machines available.</p>
      ) : (
        <>
          <div style={{ marginBottom: "20px" }}>
            <h2>Select a Machine</h2>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
              {machines.map((machine) => (
                <button
                  key={machine.id}
                  onClick={() => setSelectedMachineId(machine.id)}
                  style={{
                    padding: "10px 15px",
                    border: "1px solid #ccc",
                    borderRadius: "5px",
                    backgroundColor: selectedMachineId === machine.id ? "#007bff" : "white",
                    color: selectedMachineId === machine.id ? "white" : "black",
                    cursor: "pointer",
                    flex: "1 1 calc(50% - 10px)",
                    minWidth: "120px",
                  }}
                >
                  {machine.name}
                </button>
              ))}
            </div>
          </div>

          <div style={{ textAlign: "center" }}>
            <button
              onClick={handleReportBroken}
              disabled={selectedMachineId === null || reporting}
              style={{
                padding: "10px 20px",
                backgroundColor: selectedMachineId === null || reporting ? "#ccc" : "#dc3545",
                color: "white",
                border: "none",
                borderRadius: "5px",
                cursor: selectedMachineId === null || reporting ? "default" : "pointer",
              }}
            >
              {reporting ? "Reporting..." : "Report as Broken"}
            </button>
          </div>
        </>
      )}
    </div>
  );
}

