});

// Create new attendance record
router.post("/", (req: Request, res: Response) => {
  const { singerId, rehearsalId, present } = req.body;

  if (!singerId || !rehearsalId || present === undefined) {
    return res.status(400).json({ error: "Missing required fields: singerId, rehearsalId, present" });
  }

  const parsedSingerId = Number(singerId);
  const parsedRehearsalId = Number(rehearsalId);
  const presence = present === true ? "present" : "absent";

  if (isNaN(parsedSingerId) || isNaN(parsedRehearsalId)) {
    return res.status(400).json({ error: "Invalid singer or rehearsal ID" });
  }

  try {
    const id = insertAttendance(parsedSingerId, parsedRehearsalId, presence === "present");
    return res.status(201).json({ id, singerId: parsedSingerId, rehearsalId: parsedRehearsalId, present: presence === "present" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create attendance record" });
  }
});

// Update attendance record
router.put("/:singerId/:rehearsalId", (req: Request, res: Response) => {
  const singerId = Number(req.params.singerId);
  const rehearsalId = Number(req.params.rehearsalId);
  const { present } = req.body;

  if (isNaN(singerId) || isNaN(rehearsalId)) {
    return res.status(400).json({ error: "Invalid singer or rehearsal ID" });
  }

  if (present === undefined) {
    return res.status(400).json({ error: "Missing required field: present" });
