export function AttendanceMarkPanel() {
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [singerId, setSingerId] = useState("1"); // Default singer ID

  useEffect(() => {
    fetchAttendanceRecords();
  }, []);

  const fetchAttendanceRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/attendance-api/`);
      if (!response.ok) {
        throw new Error(`Failed to fetch records: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleMarkAttendance = async (status: "present" | "absent" | "late") => {
    try {
      const today = new Date().toISOString().split('T')[0];
      const response = await fetch(`/api/attendance-api/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          singerId,
          date: today,
          status
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to mark attendance: ${response.status}`);
      }

      await fetchAttendanceRecords();
