    return res.status(400).json({ error: "Missing required fields: singerId, rehearsalId, present" });
  }

  const parsedSingerId = Number(singerId);
  const parsedRehearsalId = Number(rehearsalId);
  const presence = present === true ? "present" : "absent";

  if (isNaN(parsedSingerId) || isNaN(parsedRehearsalId)) {
