import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check export-related requests
  if (!(req.method === "POST" && req.path === "/export/history")) {
    next();
    return;
  }

  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature using HMAC-SHA256
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const actualSignature = signature;

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(actualSignature, "base64url");

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Decode payload to check ownership
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

    // Assuming the payload contains an 'owner' field that must match a known owner ID
    // For this implementation, we'll assume owner ID is hardcoded or configurable
    const ownerId = process.env.OWNER_ID;

    if (!ownerId) {
      res.status(500).json({ error: "Server configuration error" });
      return;
    }

    if (decodedPayload.owner !== ownerId) {
      res.status(403).json({ error: "Forbidden: Export access restricted to owner" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  next();
}

import { useEffect, useState } from "react";

interface EquipmentItem {
  id: string;
  name: string;
  checkedOutBy: string | null;
  checkedOutAt: string | null;
}

export function CheckoutQueue() {
  const [equipment, setEquipment] = useState<EquipmentItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [artistName, setArtistName] = useState("");
  const [selectedToolId, setSelectedToolId] = useState<string | null>(null);

  useEffect(() => {
    fetchEquipment();
  }, []);

  const fetchEquipment = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/checkout-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setEquipment(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleCheckout = async (toolId: string) => {
    if (!artistName.trim()) {
      setError('Please enter your name');
      return;
    }

    try {
      const response = await fetch(`/api/checkout-api/${toolId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ checkedOutBy: artistName.trim() }),
      });

      if (!response.ok) {
        throw new Error(`Failed to checkout: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful checkout
      await fetchEquipment();
      setArtistName("");
      setSelectedToolId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleReturn = async (toolId: string) => {
    try {
      const response = await fetch(`/api/checkout-api/${toolId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ checkedOutBy: null, checkedOutAt: null }),
      });

      if (!response.ok) {
        throw new Error(`Failed to return: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful return
      await fetchEquipment();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async (toolId: string) => {
    try {
      const response = await fetch(`/api/checkout-api/${toolId}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful deletion
      await fetchEquipment();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedToolId) {
      handleCheckout(selectedToolId);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Equipment Checkout Queue</h1>

      {equipment.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No equipment currently checked out.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {equipment.map((item) => (
            <div 
              key={item.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                backgroundColor: item.checkedOutBy ? '#f0f8ff' : '#fff'
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <strong>{item.name}</strong>
                  {item.checkedOutBy && (
                    <div>
                      Checked out by: {item.checkedOutBy}
                      <br />
                      Checked out at: {new Date(item.checkedOutAt || '').toLocaleString()}
                    </div>
                  )}
                </div>
                <div style={{ display: 'flex', gap: '10px' }}>
                  {item.checkedOutBy ? (
                    <button 
                      onClick={() => handleReturn(item.id)}
                      style={{ 
                        backgroundColor: '#4CAF50', 
                        color: 'white', 
                        border: 'none', 
                        borderRadius: '4px', 
                        padding: '8px 12px', 
                        cursor: 'pointer' 
                      }}
                    >
                      Return
                    </button>
                  ) : (
                    <button 
                      onClick={() => {
                        setSelectedToolId(item.id);
                        setArtistName("");
                      }}
                      style={{ 
                        backgroundColor: '#2196F3', 
                        color: 'white', 
                        border: 'none', 
                        borderRadius: '4px', 
                        padding: '8px 12px', 
                        cursor: 'pointer' 
                      }}
                    >
                      Checkout
                    </button>
                  )}
                  <button 
                    onClick={() => handleDelete(item.id)}
                    style={{ 
                      backgroundColor: '#f44336', 
                      color: 'white', 
                      border: 'none', 
                      borderRadius: '4px', 
                      padding: '8px 12px', 
                      cursor: 'pointer' 
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {selectedToolId && (
        <form onSubmit={handleSubmit} style={{ marginTop: '20px', padding: '15px', border: '1px solid #ccc', borderRadius: '8px' }}>
          <h2>Check Out Tool</h2>
          <div style={{ marginBottom: '10px' }}>
            <label htmlFor="artistName">Your Name:</label>
            <input
              id="artistName"
              type="text"
              value={artistName}
              onChange={(e) => setArtistName(e.target.value)}
              style={{ 
                width: '100%', 
                padding: '8px', 
                marginTop: '5px', 
                boxSizing: 'border-box' 
              }}
              required
            />
          </div>
          <button 
            type="submit"
            style={{ 
              backgroundColor: '#2196F3', 
              color: 'white', 
              border: 'none', 
              borderRadius: '4px', 
              padding: '10px 15px', 
              cursor: 'pointer' 
            }}
          >
            Confirm Checkout
          </button>
          <button 
            type="button"
            onClick={() => setSelectedToolId(null)}
            style={{ 
              backgroundColor: '#9e9e9e', 
              color: 'white', 
              border: 'none', 
              borderRadius: '4px', 
              padding: '10px 15px', 
              marginLeft: '10px', 
              cursor: 'pointer' 
            }}
          >
            Cancel
          </button>
        </form>
      )}
    </div>
  );
}

