      res.status(403).json({ error: "Forbidden: Not the lane owner" });
    }
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

import { useEffect, useState } from "react";

interface Booking {
  id: string;
  laneId: string;
  memberId: string;
  date: string;
  startTime: string;
  endTime: string;
}

interface Lane {
  id: string;
  name: string;
  description: string;
}

export function BookingCalendar() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [lanes, setLanes] = useState<Lane[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [selectedLane, setSelectedLane] = useState<string>('');
  const [startTime, setStartTime] = useState<string>('');
  const [endTime, setEndTime] = useState<string>('');

  useEffect(() => {
    const fetchBookingsAndLanes = async () => {
      try {
        const [bookingsRes, lanesRes] = await Promise.all([
          fetch('/api/bookings-api/'),
          fetch('/api/bookings-api/lanes')
        ]);

        if (!bookingsRes.ok || !lanesRes.ok) {
          throw new Error('Failed to fetch data');
        }

        const bookingsData = await bookingsRes.json();
        const lanesData = await lanesRes.json();

        setBookings(bookingsData);
        setLanes(lanesData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchBookingsAndLanes();
  }, []);

  const handleBookLane = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedLane || !startTime || !endTime) {
      setError('Please fill in all fields');
      return;
    }

    try {
      const res = await fetch('/api/bookings-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          laneId: selectedLane,
          memberId: 'current-member-id', // This should come from auth context
          date: selectedDate,
          startTime,
          endTime
        })
      });

      if (!res.ok) {
        throw new Error('Failed to book lane');
      }

      // Refresh data after booking
      const bookingsRes = await fetch('/api/bookings-api/');
      const bookingsData = await bookingsRes.json();
      setBookings(bookingsData);

      // Reset form
      setSelectedLane('');
      setStartTime('');
      setEndTime('');
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const getAvailableSlots = () => {
    const slots = [];
    const startHour = 8;
    const endHour = 22;

    for (let hour = startHour; hour < endHour; hour++) {
      const start = `${hour}:00`;
      const end = `${hour + 1}:00`;
      slots.push({ start, end });
    }

    return slots;
  };

  const getBookedLanesForSlot = (date: string, startTime: string) => {
    return bookings
      .filter(booking => booking.date === date && booking.startTime === startTime)
      .map(booking => booking.laneId);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;
  }

  const availableSlots = getAvailableSlots();

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Booking Calendar</h1>

      <form onSubmit={handleBookLane} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2 style={{ marginTop: 0 }}>Book a Lane</h2>

        <div style={{ marginBottom: '15px' }}>
          <label>Date:</label>
          <input
            type="date"
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Lane:</label>
          <select
            value={selectedLane}
            onChange={(e) => setSelectedLane(e.target.value)}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
          >
            <option value="">Select a lane</option>
            {lanes.map(lane => (
              <option key={lane.id} value={lane.id}>{lane.name}</option>
            ))}
          </select>
        </div>

        <div style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
          <div style={{ flex: 1 }}>
            <label>Start Time:</label>
            <input
              type="time"
              value={startTime}
              onChange={(e) => setStartTime(e.target.value)}
              style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            />
          </div>
          <div style={{ flex: 1 }}>
            <label>End Time:</label>
            <input
              type="time"
              value={endTime}
              onChange={(e) => setEndTime(e.target.value)}
              style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            />
          </div>
        </div>

        <button type="submit" style={{ backgroundColor: '#007bff', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '4px', cursor: 'pointer' }}>
          Book Lane
        </button>
      </form>

      <h2>Available Slots</h2>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
        {availableSlots.map((slot, index) => {
          const bookedLanes = getBookedLanesForSlot(selectedDate, slot.start);

          return (
            <div key={index} style={{ flex: '1 1 200px', border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <h3>{slot.start} - {slot.end}</h3>
              <p>Booked lanes: {bookedLanes.length > 0 ? bookedLanes.join(', ') : 'None'}</p>
              <button 
                onClick={() => {
                  setSelectedLane(lanes[0]?.id || '');
                  setStartTime(slot.start);
                  setEndTime(slot.end);
                }}
                style={{ backgroundColor: '#28a745', color: 'white', border: 'none', padding: '8px 12px', borderRadius: '4px', cursor: 'pointer', marginTop: '10px' }}
              >
                Book Now
              </button>
            </div>
          );
        })}
      </div>

      {bookings.length === 0 && (
        <p style={{ textAlign: 'center', padding: '20px' }}>No bookings found.</p>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

export function OwnerOnlyExportPanel() {
  const [bookings, setBookings] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = () => {
    const csvContent = [
      ['ID', 'Date', 'Time', 'Lane', 'Status'],
      ...bookings.map(booking => [
        booking.id,
        booking.date,
        booking.time,
        booking.lane,
        booking.status
      ])
    ]
      .map(row => row.join(','))
      .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'booking-history.csv');
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Owner-Only Export Panel</h1>
      <p style={{ textAlign: 'center' }}>Download raw booking history report</p>

      <div style={{ marginBottom: '20px', textAlign: 'center' }}>
        <button 
          onClick={handleDownload}
          style={{
            backgroundColor: '#007bff',
            color: 'white',
            border: 'none',
            padding: '10px 20px',
            borderRadius: '5px',
            cursor: 'pointer',
            fontSize: '16px'
          }}
        >
          Download CSV Report
        </button>
      </div>

      <div style={{ textAlign: 'center', padding: '20px' }}>
        {bookings.length === 0 ? (
          <p>No bookings found.</p>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #ddd' }}>
                <th style={{ padding: '10px', textAlign: 'left' }}>ID</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Date</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Time</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Lane</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Status</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map(booking => (
                <tr key={booking.id} style={{ borderBottom: '1px solid #ddd' }}>
                  <td style={{ padding: '10px' }}>{booking.id}</td>
                  <td style={{ padding: '10px' }}>{booking.date}</td>
                  <td style={{ padding: '10px' }}>{booking.time}</td>
                  <td style={{ padding: '10px' }}>{booking.lane}</td>
                  <td style={{ padding: '10px' }}>{booking.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

