import { Router, type Request, type Response } from "express";
import {
  db,
  deleteReservation,
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation
} from "../db/reservations-table";

export const router = Router();

// GET /reservations - Get all reservations
router.get("/reservations", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// GET /reservations/:id - Get a reservation by ID
router.get("/reservations/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// POST /reservations - Create a new reservation
router.post("/reservations", (req: Request, res: Response) => {
  try {
    const { guestId, slotTime, status } = req.body;

    if (!guestId || !slotTime || !status) {
      return res.status(400).json({ error: "Missing required fields: guestId, slotTime, status" });
    }

    const id = insertReservation(guestId, slotTime, status);
    const newReservation = getReservationById(id);

    if (!newReservation) {
      return res.status(500).json({ error: "Failed to create reservation" });
    }

    res.status(201).json(newReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// PUT /reservations/:id - Update a reservation
router.put("/reservations/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { guestId, slotTime, status } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    if (!guestId || !slotTime || !status) {
      return res.status(400).json({ error: "Missing required fields: guestId, slotTime, status" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    updateReservation(id, guestId, slotTime, status);
    const updatedReservation = getReservationById(id);

    if (!updatedReservation) {
      return res.status(500).json({ error: "Failed to update reservation" });
    }

    res.json(updatedReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reservation" });
  }
});

// DELETE /reservations/:id - Delete a reservation
router.delete("/reservations/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    deleteReservation(id);
    res.json({ message: "Reservation deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete reservation" });
  }
});

