    try {
      const response = await fetch('/api/reservations-api/reservations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date: selectedDate,
          time: selectedTime,
          guestCount,
        }),
