import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./food-truck-planner.db");

interface Route {
  id: number;
  foodTruckId: number;
  date: string;
  location: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS routes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    foodTruckId INTEGER NOT NULL,
    date TEXT NOT NULL,
    location TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllRoutes(): Route[] {
  const stmt = db.prepare("SELECT * FROM routes");
  return stmt.all() as unknown as Route[];
}

export function getRouteById(id: number): Route | undefined {
  const stmt = db.prepare("SELECT * FROM routes WHERE id = ?");
  return stmt.get(id) as unknown as Route | undefined;
}

export function insertRoute(
  foodTruckId: number,
  date: string,
  location: string
): number {
  const stmt = db.prepare(
    "INSERT INTO routes (foodTruckId, date, location) VALUES (?, ?, ?)"
  );
  const result = stmt.run(foodTruckId, date, location);
  return Number(result.lastInsertRowid);
}

export function updateRoute(
  id: number,
  foodTruckId: number,
  date: string,
  location: string
): number {
  const stmt = db.prepare(
    "UPDATE routes SET foodTruckId = ?, date = ?, location = ? WHERE id = ?"
  );
  const result = stmt.run(foodTruckId, date, location, id);
  return Number(result.changes);
}

export function deleteRoute(id: number): number {
  const stmt = db.prepare("DELETE FROM routes WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

