import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("library.db");

interface Checkout {
  id: number;
  memberId: number;
  bookIds: string;
  checkoutDate: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS checkouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    memberId INTEGER NOT NULL,
    bookIds TEXT NOT NULL,
    checkoutDate TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllCheckouts(): Checkout[] {
  const stmt = db.prepare("SELECT * FROM checkouts");
  return stmt.all() as unknown as Checkout[];
}

export function getCheckoutById(id: number): Checkout | undefined {
  const stmt = db.prepare("SELECT * FROM checkouts WHERE id = ?");
  return stmt.get(id) as unknown as Checkout | undefined;
}

export function insertCheckout(memberId: number, bookIds: string, checkoutDate: string): number {
  const stmt = db.prepare(
    "INSERT INTO checkouts (memberId, bookIds, checkoutDate) VALUES (?, ?, ?)"
  );
  const result = stmt.run(memberId, bookIds, checkoutDate);
  return Number(result.lastInsertRowid);
}

export function updateCheckout(id: number, memberId: number, bookIds: string, checkoutDate: string): void {
  const stmt = db.prepare(
    "UPDATE checkouts SET memberId = ?, bookIds = ?, checkoutDate = ? WHERE id = ?"
  );
  stmt.run(memberId, bookIds, checkoutDate, id);
}

export function deleteCheckout(id: number): void {
  const stmt = db.prepare("DELETE FROM checkouts WHERE id = ?");
  stmt.run(id);
}

