import { Router, type Request, type Response } from "express";
import { db, deleteAudition, getAllAuditions, getAudition, insertAudition, updateAudition } from "../db/auditions-table";

export const router = Router();

// Get all auditions
router.get("/", (req: Request, res: Response) => {
  try {
    const auditions = getAllAuditions();
    res.json(auditions);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch auditions" });
  }
});

// Get a specific audition by actorId and slotId
router.get("/:actorId/:slotId", (req: Request, res: Response) => {
  const actorId = Number(req.params.actorId);
  const slotId = Number(req.params.slotId);

  if (isNaN(actorId) || isNaN(slotId)) {
    return res.status(400).json({ error: "Invalid actorId or slotId" });
  }

  const audition = getAudition(actorId, slotId);

  if (!audition) {
    return res.status(404).json({ error: "Audition not found" });
  }

  res.json(audition);
});

// Create a new audition
router.post("/", (req: Request, res: Response) => {
  const { actorId, slotId, isPublic } = req.body;

  if (typeof actorId !== "number" || typeof slotId !== "number" || typeof isPublic !== "boolean") {
    return res.status(400).json({ error: "Invalid input data" });
  }

  try {
    insertAudition(actorId, slotId, isPublic);
    res.status(201).json({ message: "Audition created successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to create audition" });
  }
});

// Update an existing audition
router.put("/:actorId/:slotId", (req: Request, res: Response) => {
  const actorId = Number(req.params.actorId);
  const slotId = Number(req.params.slotId);
  const { isPublic } = req.body;

  if (isNaN(actorId) || isNaN(slotId) || typeof isPublic !== "boolean") {
    return res.status(400).json({ error: "Invalid input data" });
  }

  const existingAudition = getAudition(actorId, slotId);

  if (!existingAudition) {
    return res.status(404).json({ error: "Audition not found" });
  }

  try {
    updateAudition(actorId, slotId, isPublic);
    res.json({ message: "Audition updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update audition" });
  }
});

// Delete an audition
router.delete("/:actorId/:slotId", (req: Request, res: Response) => {
  const actorId = Number(req.params.actorId);
  const slotId = Number(req.params.slotId);

  if (isNaN(actorId) || isNaN(slotId)) {
    return res.status(400).json({ error: "Invalid actorId or slotId" });
  }

  const existingAudition = getAudition(actorId, slotId);

  if (!existingAudition) {
    return res.status(404).json({ error: "Audition not found" });
  }

  try {
    deleteAudition(actorId, slotId);
    res.json({ message: "Audition deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete audition" });
  }
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to GET requests to audition entries
  if (req.method !== "GET" || !req.path.startsWith("/auditions/")) {
    next();
    return;
  }

  // Check if user is a regular member trying to access another actor's entry
  const userRole = req.headers["x-user-role"] as string | undefined;
  const userId = req.headers["x-user-id"] as string | undefined;

  // If not authenticated or not a regular member, allow access
  if (!userRole || !userId || userRole !== "member") {
    next();
    return;
  }

  // Extract actor ID from path (assuming path format: /auditions/:actorId)
  const pathParts = req.path.split("/");
  const actorId = pathParts[3];

  // If no actor ID in path, allow access
  if (!actorId) {
    next();
    return;
  }

  // Check if the requesting member is trying to access their own entry
  // For simplicity, we assume the user ID corresponds to the actor ID
  if (userId === actorId) {
    next();
    return;
  }

  // Regular member trying to access another actor's entry - reject
  res.status(403).json({ error: "Forbidden: You cannot view another actor's audition entry" });
}

import { useEffect, useState } from "react";

interface Slot {
  id: string;
  time: string;
  role: string;
  description: string;
}

interface Actor {
  id: string;
  name: string;
  email: string;
}

interface Signup {
  actorId: string;
  slotId: string;
}

export function AuditionSignupForm() {
  const [slots, setSlots] = useState<Slot[]>([]);
  const [actors, setActors] = useState<Actor[]>([]);
  const [selectedActorId, setSelectedActorId] = useState<string>("");
  const [selectedSlotId, setSelectedSlotId] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const slotsResponse = await fetch('/api/auditions-api/');
        if (!slotsResponse.ok) throw new Error('Failed to fetch slots');
        const slotsData = await slotsResponse.json();
        setSlots(slotsData);

        const actorsResponse = await fetch('/api/auditions-api/actors');
        if (!actorsResponse.ok) throw new Error('Failed to fetch actors');
        const actorsData = await actorsResponse.json();
        setActors(actorsData);

        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedActorId || !selectedSlotId) {
      setError('Please select both an actor and a slot');
      return;
    }

    try {
      const response = await fetch(`/api/auditions-api/${selectedActorId}/${selectedSlotId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ actorId: selectedActorId, slotId: selectedSlotId })
      });

      if (!response.ok) throw new Error('Failed to sign up for audition');

      // Refresh data after successful signup
      const slotsResponse = await fetch('/api/auditions-api/');
      const slotsData = await slotsResponse.json();
      setSlots(slotsData);

      // Reset form
      setSelectedActorId("");
      setSelectedSlotId("");
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Audition Signup</h1>
      <p>Please select an actor and a slot to sign up.</p>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="actorSelect" style={{ display: 'block', marginBottom: '5px' }}>
            Select Actor:
          </label>
          <select
            id="actorSelect"
            value={selectedActorId}
            onChange={(e) => setSelectedActorId(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          >
            <option value="">-- Choose an actor --</option>
            {actors.map(actor => (
              <option key={actor.id} value={actor.id}>{actor.name}</option>
            ))}
          </select>
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="slotSelect" style={{ display: 'block', marginBottom: '5px' }}>
            Select Slot:
          </label>
          <select
            id="slotSelect"
            value={selectedSlotId}
            onChange={(e) => setSelectedSlotId(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          >
            <option value="">-- Choose a slot --</option>
            {slots.map(slot => (
              <option key={slot.id} value={slot.id}>
                {slot.time} - {slot.role}
              </option>
            ))}
          </select>
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          Sign Up
        </button>
      </form>

      <h2>Available Slots</h2>
      {slots.length === 0 ? (
        <p>No slots available.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {slots.map(slot => (
            <div 
              key={slot.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '4px', 
                padding: '10px', 
                backgroundColor: '#f9f9f9' 
              }}
            >
              <strong>{slot.time}</strong> - {slot.role}
              <br />
              {slot.description}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface AuditionEntry {
  actorId: string;
  slotId: string;
  name: string;
  email: string;
  phone: string;
}

export function MemberDashboard() {
  const [auditionData, setAuditionData] = useState<AuditionEntry | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<Omit<AuditionEntry, 'actorId' | 'slotId'>>({ 
    name: '',
    email: '',
    phone: ''
  });

  useEffect(() => {
    const fetchAuditionData = async () => {
      try {
        setLoading(true);
        // In a real app, we'd get the current user's ID
        // For now, using a fixed actor ID for demonstration
        const response = await fetch(`/api/auditions-api/12345/67890`);
        if (!response.ok) {
          throw new Error(`Failed to fetch audition data: ${response.status}`);
        }
        const data = await response.json();
        setAuditionData(data);
        setFormData({
          name: data.name,
          email: data.email,
          phone: data.phone
        });
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchAuditionData();
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch(`/api/auditions-api/12345/67890`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });
      if (!response.ok) {
        throw new Error(`Failed to update audition data: ${response.status}`);
      }
      const updatedData = await response.json();
      setAuditionData(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async () => {
    try {
      const response = await fetch(`/api/auditions-api/12345/67890`, {
        method: 'DELETE'
      });
      if (!response.ok) {
        throw new Error(`Failed to delete audition data: ${response.status}`);
      }
      setAuditionData(null);
