      <h1 style={{ textAlign: 'center' }}>My Audition Entry</h1>

      {auditionData ? (
        <div>
          <div style={{ marginBottom: '20px', padding: '15px', border: '1px solid #ccc', borderRadius: '8px' }}>
            <p><strong>Name:</strong> {auditionData.name}</p>
            <p><strong>Email:</strong> {auditionData.email}</p>
            <p><strong>Phone:</strong> {auditionData.phone}</p>
          </div>

          <form onSubmit={handleSubmit} style={{ marginBottom: '20px' }}>
            <div style={{ marginBottom: '10px' }}>
              <label htmlFor="name">Name:</label>
              <input
                id="name"
                name="name"
                type="text"
                value={formData.name}
                onChange={handleInputChange}
                style={{ width: '100%', padding: '8px', marginTop: '5px' }}
              />
            </div>

            <div style={{ marginBottom: '10px' }}>
              <label htmlFor="email">Email:</label>
              <input
                id="email"
                name="email"
                type="email"
                value={formData.email}
                onChange={handleInputChange}
                style={{ width: '100%', padding: '8px', marginTop: '5px' }}
              />
            </div>

            <div style={{ marginBottom: '10px' }}>
              <label htmlFor="phone">Phone:</label>
              <input
                id="phone"
                name="phone"
                type="tel"
                value={formData.phone}
                onChange={handleInputChange}
                style={{ width: '100%', padding: '8px', marginTop: '5px' }}
              />
            </div>

            <button 
              type="submit" 
              style={{ 
                backgroundColor: '#007bff', 
                color: 'white', 
                border: 'none', 
                padding: '10px 15px', 
                borderRadius: '4px', 
                cursor: 'pointer' 
              }}
            >
              Update Entry
            </button>
          </form>

          <button 
            onClick={handleDelete}
            style={{ 
              backgroundColor: '#dc3545', 
              color: 'white', 
              border: 'none', 
              padding: '10px 15px', 
              borderRadius: '4px', 
              cursor: 'pointer' 
            }}
          >
            Delete Entry
          </button>
        </div>
      ) : (
        <div style={{ textAlign: 'center', padding: '20px' }}>
          <p>No audition entry found.</p>
        </div>
      )}
    </div>
  );
