import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to GET requests to check-in history routes
  if (req.method !== "GET" || !req.path.startsWith("/check-in-history/")) {
    next();
    return;
  }

  // In a real implementation, this would verify JWT token signature
  // For now, we'll just check if user is authenticated
  // This is a placeholder - actual implementation would check:
  // - JWT token validity
  // - User role/permissions
  // - Ownership of requested resource

  // Mock check - in reality this would be proper auth validation
  const user = (req as any).user;

  if (!user) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Extract member ID from path (e.g., /check-in-history/123)
  const pathParts = req.path.split("/");
  const requestedMemberId = pathParts[3];

  // If user is trying to access their own check-in history, allow
  if (user.memberId === requestedMemberId) {
    next();
    return;
  }

  // Otherwise, reject access
  res.status(403).json({ error: "Forbidden: Access denied" });
}

