import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./winery-harvest-log.db");

interface HarvestEntry {
  id: number;
  variety: string;
  grapes: number;
  picker_id: number;
  harvest_date: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS harvest_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    variety TEXT NOT NULL,
    grapes INTEGER NOT NULL,
    picker_id INTEGER NOT NULL,
    harvest_date TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllHarvestEntries(): HarvestEntry[] {
  const stmt = db.prepare(`SELECT * FROM harvest_entries`);
  return stmt.all() as unknown as HarvestEntry[];
}

export function getHarvestEntryById(id: number): HarvestEntry | undefined {
  const stmt = db.prepare(`SELECT * FROM harvest_entries WHERE id = ?`);
  return stmt.get(id) as unknown as HarvestEntry | undefined;
}

export function insertHarvestEntry(
  variety: string,
  grapes: number,
  picker_id: number,
  harvest_date: string
): number {
  const stmt = db.prepare(
    `INSERT INTO harvest_entries (variety, grapes, picker_id, harvest_date) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(variety, grapes, picker_id, harvest_date);
  return Number(result.lastInsertRowid);
}

export function updateHarvestEntry(
  id: number,
  variety: string,
  grapes: number,
  picker_id: number,
  harvest_date: string
): void {
  const stmt = db.prepare(
    `UPDATE harvest_entries SET variety = ?, grapes = ?, picker_id = ?, harvest_date = ? WHERE id = ?`
  );
  stmt.run(variety, grapes, picker_id, harvest_date, id);
}

export function deleteHarvestEntry(id: number): void {
  const stmt = db.prepare(`DELETE FROM harvest_entries WHERE id = ?`);
  stmt.run(id);
}

