      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface HarvestEntry {
  id: number;
  date: string;
  location: string;
  yield: number;
}

export function HarvestEntryForm() {
  const [entries, setEntries] = useState<HarvestEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [date, setDate] = useState("");
  const [location, setLocation] = useState("");
  const [yieldValue, setYield] = useState("");

  const inputStyle = {
    width: "100%",
    padding: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    boxSizing: "border-box" as const,
  };

  const entriesContainerStyle = {
    display: "flex" as const,
    flexWrap: "wrap" as const,
    gap: "15px" as const,
  };

  const cardStyle = {
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "15px",
    width: "100%",
    maxWidth: "300px",
    boxSizing: "border-box" as const,
  };

  const buttonStyle = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    padding: "10px 15px",
    cursor: "pointer" as const,
    fontSize: "16px",
    width: "100%",
  };

  const fetchEntries = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/harvest-entries-api/");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setEntries(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEntries();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!date || !location || !yieldValue) {
      setError("All fields are required.");
      return;
    }

    try {
      const response = await fetch("/api/harvest-entries-api/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          date,
          location,
          yield: Number(yieldValue),
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Reset form
      setDate("");
      setLocation("");
      setYield("");

      // Refresh entries
      await fetchEntries();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div>Loading...</div>;

  if (error) return <div>Error: {error}</div>;

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
    }}>
      <h1>Harvest Entry Form</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label>Date:
            <input
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              style={inputStyle}
            />
          </label>
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label>Location:
            <input
              type="text"
              value={location}
              onChange={(e) => setLocation(e.target.value)}
              style={inputStyle}
            />
          </label>
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label>Yield (kg):
            <input
              type="number"
              value={yieldValue}
              onChange={(e) => setYield(e.target.value)}
              style={inputStyle}
            />
          </label>
        </div>

        <button type="submit" style={buttonStyle}>Add Entry</button>
      </form>

      <h2>Harvest Entries</h2>

      {entries.length === 0 ? (
        <p>No harvest entries found.</p>
      ) : (
        <div style={entriesContainerStyle}>
          {entries.map((entry) => (
            <div key={entry.id} style={cardStyle}>
              <p><strong>Date:</strong> {entry.date}</p>
              <p><strong>Location:</strong> {entry.location}</p>
              <p><strong>Yield:</strong> {entry.yield} kg</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./data.db");

interface BoxCustomization {
  id: number;
  member_id: number;
  contents: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS box_customizations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id INTEGER NOT NULL,
    contents TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllBoxCustomizations(): BoxCustomization[] {
  const stmt = db.prepare("SELECT * FROM box_customizations");
  return stmt.all() as unknown as BoxCustomization[];
}

export function getBoxCustomizationById(id: number): BoxCustomization | undefined {
  const stmt = db.prepare("SELECT * FROM box_customizations WHERE id = ?");
  return stmt.get(id) as unknown as BoxCustomization | undefined;
}

export function insertBoxCustomization(memberId: number, contents: string): number {
  const stmt = db.prepare(
    "INSERT INTO box_customizations (member_id, contents) VALUES (?, ?)"
  );
  const result = stmt.run(memberId, contents);
  return Number(result.lastInsertRowid);
}

export function updateBoxCustomization(
  id: number,
  memberId: number,
  contents: string
): void {
  const stmt = db.prepare(
    "UPDATE box_customizations SET member_id = ?, contents = ? WHERE id = ?"
  );
  stmt.run(memberId, contents, id);
}

export function deleteBoxCustomization(id: number): void {
  const stmt = db.prepare("DELETE FROM box_customizations WHERE id = ?");
  stmt.run(id);
}

