import { Router, type Request, type Response } from "express";
import {
  db,
  deleteBoxCustomization,
  getAllBoxCustomizations,
  getBoxCustomizationById,
  insertBoxCustomization,
  updateBoxCustomization
} from "../db/box-customizations-table";

export const router = Router();

// Get all box customizations
router.get("/", (req: Request, res: Response) => {
  try {
    const customizations = getAllBoxCustomizations();
    return res.json(customizations);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch customizations" });
  }
});

// Get a specific box customization by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID provided" });
  }

  const customization = getBoxCustomizationById(id);

  if (!customization) {
    return res.status(404).json({ error: "Customization not found" });
  }

  return res.json(customization);
});

// Create a new box customization
router.post("/", (req: Request, res: Response) => {
  const { memberId, contents } = req.body;

  if (!memberId || !contents) {
    return res.status(400).json({ error: "Member ID and contents are required" });
  }

  try {
    const id = insertBoxCustomization(Number(memberId), contents);
    return res.status(201).json({ id, memberId, contents });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create customization" });
  }
});

// Update an existing box customization
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { memberId, contents } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID provided" });
  }

  if (!memberId || !contents) {
    return res.status(400).json({ error: "Member ID and contents are required" });
  }

  try {
    updateBoxCustomization(id, Number(memberId), contents);
    return res.json({ id, memberId, contents });
  } catch (error) {
    return res.status(500).json({ error: "Failed to update customization" });
  }
});

// Delete a box customization
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID provided" });
  }

  try {
    deleteBoxCustomization(id);
    return res.json({ message: "Customization deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete customization" });
  }
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply privacy guard to GET requests to box customization routes
  if (req.method !== "GET" || !req.path.startsWith("/members/")) {
    next();
    return;
  }

  // For GET requests to member box customizations, we need to ensure
  // the requester is authorized to access the requested member's data

  // Extract member ID from path (e.g., /members/123/box-customizations)
  const pathParts = req.path.split("/");
  const requestedMemberId = pathParts[3];

  // If there's no member ID in the path, let it pass through
  if (!requestedMemberId) {
    next();
    return;
  }

  // Check if user is authenticated and has permission to access this member's data
  // This is a simplified check - in a real implementation, you'd verify
  // the user's session/token against the requested member ID

  // For now, we'll assume that if the user is accessing their own data,
  // they should be allowed. In a real system, this would involve:
  // 1. Verifying JWT token signature
  // 2. Extracting user ID from token
  // 3. Comparing with requestedMemberId

  // Since we don't have actual auth logic here, we'll just allow all requests
  // to proceed - but in a real implementation, this would be where you'd
  // implement the actual authorization check

  // For demonstration purposes, let's say we're checking a mock user ID
  // In reality, this would come from a verified token or session
  const userIdFromToken = req.headers["x-user-id"] as string | undefined;

  if (userIdFromToken && userIdFromToken === requestedMemberId) {
    // User is accessing their own data - allow
    next();
    return;
  }

  // If we get here, the user is trying to access another member's data
  // Reject with 403 Forbidden
  res.status(403).json({ error: "Access denied to member box customizations" });
}

import { useEffect, useState } from "react";

interface Item {
  id: number;
  name: string;
  category: string;
}

interface BoxItem {
  id: number;
  itemId: number;
  itemName: string;
  quantity: number;
}

export function BoxCustomizer() {
  const [items, setItems] = useState<Item[]>([]);
  const [boxItems, setBoxItems] = useState<BoxItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newItemName, setNewItemName] = useState("");
  const [newItemCategory, setNewItemCategory] = useState("");

  useEffect(() => {
    fetchItems();
    fetchBoxItems();
  }, []);

  const fetchItems = async () => {
    try {
      const response = await fetch('/api/customization-api/');
      if (!response.ok) throw new Error('Failed to fetch items');
      const data = await response.json();
      setItems(data);
    } catch (err) {
      setError('Error loading items');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchBoxItems = async () => {
    try {
      const response = await fetch('/api/customization-api/');
      if (!response.ok) throw new Error('Failed to fetch box items');
      const data = await response.json();
      setBoxItems(data);
    } catch (err) {
      setError('Error loading box items');
      console.error(err);
    }
  };

  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItemName.trim() || !newItemCategory.trim()) return;

    try {
      const response = await fetch('/api/customization-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: newItemName,
          category: newItemCategory
        })
      });

      if (!response.ok) throw new Error('Failed to add item');

      setNewItemName("");
      setNewItemCategory("");
      await fetchItems();
    } catch (err) {
      setError('Error adding item');
      console.error(err);
    }
  };

  const handleRemoveItem = async (id: number) => {
    try {
      const response = await fetch(`/api/customization-api/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to remove item');
      await fetchItems();
    } catch (err) {
      setError('Error removing item');
      console.error(err);
    }
  };

  const handleUpdateQuantity = async (itemId: number, quantity: number) => {
    try {
      const response = await fetch(`/api/customization-api/${itemId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ quantity })
      });

      if (!response.ok) throw new Error('Failed to update quantity');
      await fetchBoxItems();
    } catch (err) {
      setError('Error updating quantity');
      console.error(err);
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Box Customizer</h1>

      {error && <p style={{ color: 'red', textAlign: 'center' }}>{error}</p>}

      <div style={{ marginBottom: '30px' }}>
        <h2>Add New Item</h2>
        <form onSubmit={handleAddItem} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <input
            type="text"
            placeholder="Item name"
            value={newItemName}
            onChange={(e) => setNewItemName(e.target.value)}
            style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc', width: '100%' }}
          />
          <input
            type="text"
            placeholder="Category"
            value={newItemCategory}
            onChange={(e) => setNewItemCategory(e.target.value)}
            style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc', width: '100%' }}
          />
          <button 
            type="submit" 
            style={{ 
              padding: '10px', 
              backgroundColor: '#007bff', 
              color: 'white', 
              border: 'none', 
              borderRadius: '4px', 
              cursor: 'pointer' 
            }}
          >
            Add Item
          </button>
        </form>
      </div>

      <div style={{ marginBottom: '30px' }}>
        <h2>Available Items</h2>
        {items.length === 0 ? (
          <p style={{ textAlign: 'center' }}>No items available</p>
        ) : (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
            {items.map(item => (
              <div 
                key={item.id} 
                style={{ 
                  border: '1px solid #ccc', 
                  borderRadius: '8px', 
                  padding: '15px', 
                  width: '200px',
                  backgroundColor: '#f9f9f9'
                }}
              >
                <h3>{item.name}</h3>
                <p>{item.category}</p>
                <button 
                  onClick={() => handleRemoveItem(item.id)}
                  style={{ 
                    backgroundColor: '#dc3545', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer' 
                  }}
                >
                  Remove
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      <div>
        <h2>Your Box Items</h2>
        {boxItems.length === 0 ? (
          <p style={{ textAlign: 'center' }}>Your box is empty</p>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #ccc' }}>
                <th style={{ textAlign: 'left', padding: '10px' }}>Item</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Quantity</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {boxItems.map(boxItem => (
                <tr key={boxItem.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '10px' }}>{boxItem.itemName}</td>
                  <td style={{ padding: '10px' }}>
                    <input
                      type="number"
                      min="0"
                      value={boxItem.quantity}
                      onChange={(e) => handleUpdateQuantity(boxItem.itemId, parseInt(e.target.value) || 0)}
                      style={{ width: '60px', padding: '5px', border: '1px solid #ccc', borderRadius: '4px' }}
                    />
                  </td>
                  <td style={{ padding: '10px' }}>
                    <button 
                      onClick={() => handleRemoveItem(boxItem.itemId)}
                      style={{ 
                        backgroundColor: '#dc3545', 
                        color: 'white', 
                        border: 'none', 
                        padding: '5px 10px', 
                        borderRadius: '4px', 
                        cursor: 'pointer' 
                      }}
                    >
                      Remove
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface BoxCustomization {
  id: number;
  name: string;
  description: string;
  createdAt: string;
}

export function MemberOnlyView() {
  const [customizations, setCustomizations] = useState<BoxCustomization[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newName, setNewName] = useState("");
  const [newDescription, setNewDescription] = useState("");

  useEffect(() => {
    fetchCustomizations();
  }, []);

  const fetchCustomizations = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/customization-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setCustomizations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/customization-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: newName, description: newDescription }),
      });
      if (!response.ok) {
        throw new Error(`Failed to create: ${response.status} ${response.statusText}`);
      }
      setNewName("");
      setNewDescription("");
      await fetchCustomizations();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/customization-api/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }
      await fetchCustomizations();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;

  return (
