      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {customizations.map((item) => (
            <div key={item.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <h3>{item.name}</h3>
              <p>{item.description}</p>
              <p style={{ fontSize: '0.9em', color: '#666' }}>
                Created: {new Date(item.createdAt).toLocaleDateString()}
              </p>
              <button 
                onClick={() => handleDelete(item.id)}
                style={{ 
                  backgroundColor: '#ff4d4d', 
                  color: 'white', 
                  border: 'none', 
                  borderRadius: '4px', 
                  padding: '8px 12px', 
                  marginTop: '10px', 
                  cursor: 'pointer'
                }}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      )}

      <form onSubmit={handleCreate} style={{ marginTop: '30px', padding: '20px', border: '1px solid #eee', borderRadius: '8px' }}>
        <h2>Create New Customization</h2>
        <div style={{ marginBottom: '10px' }}>
          <label htmlFor="name" style={{ display: 'block', marginBottom: '5px' }}>Name:</label>
          <input
            id="name"
            type="text"
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            required
          />
        </div>
        <div style={{ marginBottom: '10px' }}>
          <label htmlFor="description" style={{ display: 'block', marginBottom: '5px' }}>Description:</label>
          <textarea
            id="description"
            value={newDescription}
            onChange={(e) => setNewDescription(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc', minHeight: '60px' }}
            required
          />
        </div>
        <button 
          type="submit"
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            borderRadius: '4px', 
            padding: '10px 20px', 
            cursor: 'pointer'
          }}
        >
          Create
        </button>
      </form>
    </div>
  );
